              - 100.*s*(1.-s)**4 *t**3 *(1.-t) + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2
    H_t(7,4) = -50.*s**2 *(1.-s)**3 *t**4 - 200.*s**2 *(1.-s)**3 *t**3 *(1.-t) &
              + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(8,4) = -100.*s*(1.-s)**4 *t**3 *(1.-t) + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2 &
              - 400.*s**2 *(1.-s)**3 *t**3 *(1.-t) + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(9,4) = -200.*s**2 *(1.-s)**3 *t**3 *(1.-t) + 300.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
  endif
end subroutine basisfunctions_2D_1_T
  
  
!> Basisfunctions in 2D with first and cross-derivative
pure subroutine basisfunctions_2D_1p(s,t,H,H_s,H_t,H_st)
  implicit none
  real*8, intent(in)  :: s                   !< s-coordinate in the element [0,1]
  real*8, intent(in)  :: t                   !< t-coordinate in the element [0,1]
  real*8, intent(out) :: H   (4,n_order+1)   !< Basis functions
  real*8, intent(out) :: H_s (4,n_order+1)   !< Basis functions derived with respect to s
  real*8, intent(out) :: H_t (4,n_order+1)   !< Basis functions derived with respect to t
  real*8, intent(out) :: H_st(4,n_order+1)   !< Basis functions derived with respect to s and t
  
  ! --- Local variables
  real*8 :: scale1, dscale1_ds, dscale1_dt, dscale1_dsdt
  real*8 :: scale2, dscale2_ds, dscale2_dt, dscale2_dsdt
  real*8 :: scale3, dscale3_ds, dscale3_dt, dscale3_dsdt
  real*8 :: scale4, dscale4_ds, dscale4_dt, dscale4_dsdt
  
  real*8 :: h11, h12, h13, h14, h11_s, h12_s, h13_s, h14_s, h11_t, h12_t, h13_t, h14_t, h11_st, h12_st, h13_st, h14_st
  real*8 :: h21, h22, h23, h24, h21_s, h22_s, h23_s, h24_s, h21_t, h22_t, h23_t, h24_t, h21_st, h22_st, h23_st, h24_st
  real*8 :: h31, h32, h33, h34, h31_s, h32_s, h33_s, h34_s, h31_t, h32_t, h33_t, h34_t, h31_st, h32_st, h33_st, h34_st
  real*8 :: h41, h42, h43, h44, h41_s, h42_s, h43_s, h44_s, h41_t, h42_t, h43_t, h44_t, h41_st, h42_st, h43_st, h44_st
  
  ! --- CUBIC
  if (n_order .eq. 3) then
    scale1       =      (s-1.d0)**2 * (t-1.d0)**2
    dscale1_ds   = 2.d0*(s-1.d0)    * (t-1.d0)**2
    dscale1_dt   = 2.d0*(t-1.d0)    * (s-1.d0)**2
    dscale1_dsdt = 4.d0*(s-1.d0)    * (t-1.d0)
    
    h11 = (1.d0+2.d0*s)*(1.d0+2.d0*t); h11_s = 2.d0*(1.d0+2.d0*t); h11_t = 2.d0*(1.d0+2.d0*s); h11_st = 4.d0
    h12 = 3.d0*s * (1.d0+2.d0*t)     ; h12_s = 3.d0*(1.d0+2.d0*t); h12_t = 6.d0*s            ; h12_st = 6.d0
    h13 = 3.d0*t * (1.d0+2.d0*s)     ; h13_s = 6.d0*t            ; h13_t = 3.d0*(1.d0+2.d0*s); h13_st = 6.d0
    h14 = 9.d0*s*t                   ; h14_s = 9.d0*t            ; h14_t = 9.d0*s            ; h14_st = 9.d0
    
    H(1,1) = scale1 * h11
    H(1,2) = scale1 * h12
    H(1,3) = scale1 * h13
    H(1,4) = scale1 * h14
    
    H_s(1,1) = dscale1_ds * h11  + scale1 * h11_s
    H_s(1,2) = dscale1_ds * h12  + scale1 * h12_s
    H_s(1,3) = dscale1_ds * h13  + scale1 * h13_s
    H_s(1,4) = dscale1_ds * h14  + scale1 * h14_s
    
    H_t(1,1) = dscale1_dt * h11  + scale1 * h11_t
    H_t(1,2) = dscale1_dt * h12  + scale1 * h12_t
    H_t(1,3) = dscale1_dt * h13  + scale1 * h13_t
    H_t(1,4) = dscale1_dt * h14  + scale1 * h14_t
    
    H_st(1,1) = dscale1_dsdt * h11  + dscale1_dt * h11_s  +  dscale1_ds * h11_t  + scale1 * h11_st
    H_st(1,2) = dscale1_dsdt * h12  + dscale1_dt * h12_s  +  dscale1_ds * h12_t  + scale1 * h12_st
    H_st(1,3) = dscale1_dsdt * h13  + dscale1_dt * h13_s  +  dscale1_ds * h13_t  + scale1 * h13_st
    H_st(1,4) = dscale1_dsdt * h14  + dscale1_dt * h14_s  +  dscale1_ds * h14_t  + scale1 * h14_st
    
    !----------------------------------------------------------------------------
    scale2       =       s**2 *      (t-1.d0)**2
    dscale2_ds   =  2.d0*s    *      (t-1.d0)**2
    dscale2_dt   =       s**2 * 2.d0*(t-1.d0)
    dscale2_dsdt =  4.d0*s    *      (t-1.d0)
    
    h21 = (3.d0-2.d0*s)*(1.d0+2.d0*t); h21_s = -2.d0*(1.d0+2.d0*t) ; h21_t =  2.d0*(3.d0-2.d0*s) ; h21_st = -4.d0
    h22 = 3.d0*(1.d0-s)*(1.d0+2.d0*t); h22_s = -3.d0*(1.d0+2.d0*t) ; h22_t =  6.d0*(1.d0-s)      ; h22_st = -6.d0
    h23 = 3.d0*(3.d0-2.d0*s)*t       ; h23_s = -6.d0*t             ; h23_t =  3.d0*(3.d0-2.d0*s) ; h23_st = -6.d0
    h24 = 9.d0*(1.d0-s)* t           ; h24_s = -9.d0*t             ; h24_t =  9.d0*(1.d0-s)      ; h24_st = -9.d0
    
    H(2,1) = scale2 * h21
    H(2,2) = scale2 * h22
    H(2,3) = scale2 * h23
    H(2,4) = scale2 * h24
    
    H_s(2,1) = dscale2_ds * h21 + scale2 * h21_s
    H_s(2,2) = dscale2_ds * h22 + scale2 * h22_s
    H_s(2,3) = dscale2_ds * h23 + scale2 * h23_s
    H_s(2,4) = dscale2_ds * h24 + scale2 * h24_s
    
    H_t(2,1) = dscale2_dt * h21 + scale2 * h21_t
    H_t(2,2) = dscale2_dt * h22 + scale2 * h22_t
    H_t(2,3) = dscale2_dt * h23 + scale2 * h23_t
    H_t(2,4) = dscale2_dt * h24 + scale2 * h24_t
    
    H_st(2,1) = dscale2_dsdt * h21 + dscale2_dt * h21_s +  dscale2_ds * h21_t + scale2 * h21_st
    H_st(2,2) = dscale2_dsdt * h22 + dscale2_dt * h22_s +  dscale2_ds * h22_t + scale2 * h22_st
    H_st(2,3) = dscale2_dsdt * h23 + dscale2_dt * h23_s +  dscale2_ds * h23_t + scale2 * h23_st
    H_st(2,4) = dscale2_dsdt * h24 + dscale2_dt * h24_s +  dscale2_ds * h24_t + scale2 * h24_st
    
    
    !----------------------------------------------------------------------------
    scale3       =      s**2 *      t**2
    dscale3_ds   = 2.d0*s    *      t**2
    dscale3_dt   =      s**2 * 2.d0*t
    dscale3_dsdt = 4.d0*s    *      t
    
    h31 = (3.d0-2.d0*s)*(3.d0-2.d0*t) ; h31_s = -2.d0*(3.d0-2.d0*t) ;  h31_t = -2.d0*(3.d0-2.d0*s) ;  h31_st = +4.d0
    h32 = 3.d0*(1.d0-s)*(3.d0-2.d0*t) ; h32_s = -3.d0*(3.d0-2.d0*t) ;  h32_t = -6.d0*(1.d0-s)      ;  h32_st = +6.d0
    h33 = 3.d0*(3.d0-2.*s)*(1.d0-t)   ; h33_s = -6.d0*(1.d0-t)      ;  h33_t = -3.d0*(3.d0-2.d0*s) ;  h33_st = +6.d0
    h34 = 9.d0*(1.d0-s)*(1.d0-t)      ; h34_s = -9.d0*(1.d0-t)      ;  h34_t = -9.d0*(1.d0-s)      ;  h34_st = +9.d0
    
    H(3,1) = scale3 * h31
    H(3,2) = scale3 * h32
    H(3,3) = scale3 * h33
    H(3,4) = scale3 * h34
    
    H_s(3,1) = dscale3_ds * h31 + scale3 * h31_s
    H_s(3,2) = dscale3_ds * h32 + scale3 * h32_s
    H_s(3,3) = dscale3_ds * h33 + scale3 * h33_s
    H_s(3,4) = dscale3_ds * h34 + scale3 * h34_s
    
    H_t(3,1) = dscale3_dt * h31 + scale3 * h31_t
    H_t(3,2) = dscale3_dt * h32 + scale3 * h32_t
    H_t(3,3) = dscale3_dt * h33 + scale3 * h33_t
    H_t(3,4) = dscale3_dt * h34 + scale3 * h34_t
    
    H_st(3,1) = dscale3_dsdt * h31 + dscale3_dt * h31_s + dscale3_ds * h31_t + scale3 * h31_st
    H_st(3,2) = dscale3_dsdt * h32 + dscale3_dt * h32_s + dscale3_ds * h32_t + scale3 * h32_st
    H_st(3,3) = dscale3_dsdt * h33 + dscale3_dt * h33_s + dscale3_ds * h33_t + scale3 * h33_st
    H_st(3,4) = dscale3_dsdt * h34 + dscale3_dt * h34_s + dscale3_ds * h34_t + scale3 * h34_st
    
    !----------------------------------------------------------------------------
    scale4       =       (s-1.d0)**2 *      t**2
    dscale4_ds   =  2.d0*(s-1.d0)    *      t**2
    dscale4_dt   =       (s-1.d0)**2 * 2.d0*t
    dscale4_dsdt =  4.d0*(s-1.d0)    *      t
    
    h41    =  (1.d0+2.d0*s)*(3.d0-2.d0*t);  h41_s = 2.d0*(3.d0-2.d0*t);  h41_t = -2.d0*(1.d0+2.d0*s) ;  h41_st =-4.d0
    h42    = 3.d0*s*(3.d0-2.d0*t)        ;  h42_s = 3.d0*(3.d0-2.d0*t);  h42_t = -6.d0*s             ;  h42_st =-6.d0
    h43    = 3.d0*(1.d0+2.d0*s)*(1.-t)   ;  h43_s = 6.d0*(1.d0-t)     ;  h43_t = -3.d0*(1.d0+2.d0*s) ;  h43_st =-6.d0
    h44    = 9.d0*s*(1.d0-t)             ;  h44_s = 9.d0*(1.d0-t)     ;  h44_t = -9.d0*s             ;  h44_st =-9.d0
    
    H(4,1) = scale4 * h41
    H(4,2) = scale4 * h42
    H(4,3) = scale4 * h43
    H(4,4) = scale4 * h44
    
    H_s(4,1) = dscale4_ds * h41 + scale4 *  h41_s
    H_s(4,2) = dscale4_ds * h42 + scale4 *  h42_s
    H_S(4,3) = dscale4_ds * h43 + scale4 *  h43_s
    H_s(4,4) = dscale4_ds * h44 + scale4 *  h44_s
    
    H_t(4,1) = dscale4_dt * h41  + scale4 * h41_t
    H_t(4,2) = dscale4_dt * h42  + scale4 * h42_t
    H_t(4,3) = dscale4_dt * h43  + scale4 * h43_t
    H_t(4,4) = dscale4_dt * h44  + scale4 * h44_t
    
    H_st(4,1) = dscale4_dsdt * h41 + dscale4_dt * h41_s +  dscale4_ds * h41_t + scale4 * h41_st
    H_st(4,2) = dscale4_dsdt * h42 + dscale4_dt * h42_s +  dscale4_ds * h42_t + scale4 * h42_st
    H_st(4,3) = dscale4_dsdt * h43 + dscale4_dt * h43_s +  dscale4_ds * h43_t + scale4 * h43_st
    H_st(4,4) = dscale4_dsdt * h44 + dscale4_dt * h44_s +  dscale4_ds * h44_t + scale4 * h44_st
  ! --- QUINTIC
  else
    call basisfunctions_2D_1(s, t, H, H_s, H_t)
      
    !---------------------------------------------------------- vertex (1)
    H_st(1,1) = 900.*s**2 * (1.-s)**2 * t**2 * (1.-t)**2
    H_st(1,2) = - 400.*s*(1.-s)**3 *t*(1.-t)**3 - 100.*(1.-s)**4 *t*(1.-t)**3 &
               + 1200.*s**2 * (1.-s)**2 *t*(1.-t)**3
    H_st(1,3) = -400.*s*(1.-s)**3 *t*(1.-t)**3 - 100.*s*(1.-s)**3 *(1.-t)**4 &
               + 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(1,4) = 400.*s*(1.-s)**3 *t*(1.-t)**3 + 100.*s*(1.-s)**3 *(1.-t)**4 &
               + 100.*(1.-s)**4 *t*(1.-t)**3 + 25.*(1.-s)**4 *(1.-t)**4 &
               - 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 300.*s**2 * (1.-s)**2 *(1.-t)**4 &
               - 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2 - 300.*(1.-s)**4 *t**2 *(1.-t)**2 &
               + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(1,5) = + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 400.*s *(1.-s)**3 *t*(1.-t)**3
    H_st(1,6) = 600.*s*(1.-s)**3 *t**2 *(1.-t)**2 - 400.*s*(1.-s)**3 *t*(1.-t)**3
    H_st(1,7) = -600.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 150.*s**2 *(1.-s)**2 *(1.-t)**4 &
               + 400.*s *(1.-s)**3 *t*(1.-t)**3 + 100.*s *(1.-s)**3 *(1.-t)**4 &
               + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 1200.*s *(1.-s)**3 *t**2 *(1.-t)**2
    H_st(1,8) = -600.*s*(1.-s)**3 *t**2 *(1.-t)**2 + 400.*s*(1.-s)**3 *t*(1.-t)**3 &
               - 150.*(1.-s)**4 *t**2 *(1.-t)**2 + 100.*(1.-s)**4 *t*(1.-t)**3 &
               + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(1,9) = 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 &
               - 600.*s *(1.-s)**3 *t**2 *(1.-t)**2 + 400.*s *(1.-s)**3 *t*(1.-t)**3
    !---------------------------------------------------------- vertex (2)
    H_st(2,1) = - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,2) = + 100.*s**4 *t*(1.-t)**3 + 400.*s**3 *(1.-s)*t*(1.-t)**3 &
               - 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(2,3) = 400.*s**3 *(1.-s)*t*(1.-t)**3 + 100.*s**3 *(1.-s)*(1.-t)**4 &
               - 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2
    H_st(2,4) = -100.*s**4 *t*(1.-t)**3 - 25.*s**4 *(1.-t)**4 - 400.*s**3 *(1.-s)*t*(1.-t)**3 &
               - 100.*s**3 *(1.-s)*(1.-t)**4 + 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3 &
               + 300.*s**2 *(1.-s)**2 *(1.-t)**4 + 300.*s**4 *t**2 *(1.-t)**2 &
               + 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,5) = + 400.*s**3 *(1.-s) *t*(1.-t)**3 - 600.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(2,6) = -600.*s**3 *(1.-s) *t**2 *(1.-t)**2 + 400.*s**3 *(1.-s) *t*(1.-t)**3
    H_st(2,7) = -400.*s**3 *(1.-s)*t*(1.-t)**3 - 100.*s**3 *(1.-s)*(1.-t)**4 &
               + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 + 150.*s**2 *(1.-s)**2 *(1.-t)**4 &
               + 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,8) = 150.*s**4 *t**2 *(1.-t)**2 - 100.*s**4 *t*(1.-t)**3 &
               + 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 400.*s**3 *(1.-s) *t*(1.-t)**3 &
               - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 + 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(2,9) = 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 400.*s**3 *(1.-s) *t*(1.-t)**3 &
               - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3
    !---------------------------------------------------------- vertex (3)
    H_st(3,1) = + 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 
    H_st(3,2) = - 100.*s**4 *t**3 *(1.-t) - 400.*s**3 *(1.-s) *t**3 *(1.-t) &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(3,3) = - 100.*s**3 *(1.-s) *t**4 - 400.*s**3 *(1.-s) *t**3 *(1.-t) &
               + 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2
    H_st(3,4) = 25.*s**4 *t**4 + 100.*s**4 *t**3 *(1.-t) + 100.*s**3 *(1.-s) *t**4 &
               + 400.*s**3 *(1.-s) *t**3 *(1.-t) - 300.*s**2 *(1.-s)**2 *t**4 &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 300.*s**4 *t**2 *(1.-t)**2 &
               - 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(3,5) = - 400.*s**3 *(1.-s) *t**3 *(1.-t) + 600.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(3,6) = -400.*s**3 *(1.-s) *t**3 *(1.-t) + 600.*s**3 *(1.-s) *t**2 *(1.-t)**2
    H_st(3,7) = 100.*s**3 *(1.-s) *t**4 + 400.*s**3 *(1.-s) *t**3 *(1.-t) &
               - 150.*s**2 *(1.-s)**2 *t**4 - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) &
               - 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 
    H_st(3,8) = 100.*s**4 *t**3 *(1.-t) - 150.*s**4 *t**2 *(1.-t)**2 &
               + 400.*s**3 *(1.-s) *t**3 *(1.-t) - 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(3,9) = 400.*s**3 *(1.-s) *t**3 *(1.-t) - 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 &
               - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    !---------------------------------------------------------- vertex (4)
    H_st(4,1) = - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(4,2) = + 400.*s*(1.-s)**3 *t**3 *(1.-t) + 100.*(1.-s)**4 *t**3 *(1.-t) &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(4,3) = + 100.*s*(1.-s)**3 *t**4 + 400.*s*(1.-s)**3 *t**3 *(1.-t) &
               - 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,4) = -100.*s*(1.-s)**3 *t**4 - 400.*s*(1.-s)**3 *t**3 *(1.-t) - 25.*(1.-s)**4 *t**4 &
               - 100.*(1.-s)**4 *t**3 *(1.-t) + 300.*s**2 *(1.-s)**2 *t**4 &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2 &
               + 300.*(1.-s)**4 *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(4,5) = - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 400.*s *(1.-s)**3 *t**3 *(1.-t)
    H_st(4,6) = 400.*s*(1.-s)**3 *t**3 *(1.-t) - 600.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,7) = 150.*s**2 *(1.-s)**2 *t**4 - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) &
               - 100.*s *(1.-s)**3 *t**4 + 400.*s *(1.-s)**3 *t**3 *(1.-t) &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 &
               - 800.*s *(1.-s)**3 *t**3 *(1.-t) + 1200.*s *(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,8) = -400.*s*(1.-s)**3 *t**3 *(1.-t) + 600.*s*(1.-s)**3 *t**2 *(1.-t)**2 &
               - 100.*(1.-s)**4 *t**3 *(1.-t) + 150.*(1.-s)**4 *t**2 *(1.-t)**2 &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(4,9) = 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 &
               - 400.*s *(1.-s)**3 *t**3 *(1.-t) + 600.*s *(1.-s)**3 *t**2 *(1.-t)**2
  endif
end subroutine basisfunctions_2D_1p
  
  
!> Basisfunctions with second derivatives in 2D
pure subroutine basisfunctions_2D_2(s, t, H, H_s, H_t, H_st, H_ss, H_tt)
  implicit none
  real*8, intent(in)  :: s                  !< s-coordinate in the element [0,1]
  real*8, intent(in)  :: t                  !< t-coordinate in the element [0,1]
  real*8, intent(out) :: H   (4,n_order+1)  !< Basis functions
  real*8, intent(out) :: H_s (4,n_order+1)  !< Basis functions derived with respect to s
  real*8, intent(out) :: H_t (4,n_order+1)  !< Basis functions derived with respect to t
  real*8, intent(out) :: H_st(4,n_order+1)  !< Basis functions derived with respect to s and t
  real*8, intent(out) :: H_ss(4,n_order+1)  !< Basis functions derived two times with respect to s
  real*8, intent(out) :: H_tt(4,n_order+1)  !< Basis functions derived two times with respect to t
  
  call basisfunctions_2D_1(s, t, H, H_s, H_t)
  
  ! --- CUBIC
  if (n_order .eq. 3) then
    !---------------------------------------------------------- vertex (1)
    H_st(1,1)=36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(1,1)=6.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_tt(1,1)=6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(1,2)=18.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*(-1.d0 + t)*t
    H_ss(1,2)=6.d0*(-2.d0 + 3.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_tt(1,2)=18.d0*(-1.d0 + s)**2*s*(-1.d0 + 2.d0*t)
    H_st(1,3)=18.d0*(-1.d0 + s)*s*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(1,3)=18.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)**2*t
    H_tt(1,3)=6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-2.d0 + 3.d0*t)
    H_st(1,4)=9.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(1,4)=18.d0*(-2.d0 + 3.d0*s)*(-1.d0 + t)**2*t
    H_tt(1,4)=18.d0*(-1.d0 + s)**2*s*(-2.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (2)
    H_st(2,1)=-36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(2,1)=-6.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_tt(2,1)=-6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(2,2)=-18.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t
    H_ss(2,2)=-6.d0*(-1.d0 + 3.d0*s)*(-1.d0 + t)**2*(1 + 2.d0*t)
    H_tt(2,2)=-18.d0*(-1.d0 + s)*s**2*(-1.d0 + 2.d0*t)
    H_st(2,3)=-18.d0*(-1.d0 + s)*s*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(2,3)=6.d0*(3.d0 - 6.d0*s)*(-1.d0 + t)**2*t
    H_tt(2,3)=-6.d0*s**2*(-3.d0 + 2.d0*s)*(-2.d0 + 3.d0*t)
    H_st(2,4)=-9.d0*s*(-2.d0 + 3.d0*s)*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(2,4)=18.d0*(1.d0 - 3.d0*s)*(-1.d0 + t)**2*t
    H_tt(2,4)=-18.d0*(-1.d0 + s)*s**2*(-2.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (3)
    H_st(3,1)=36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(3,1)=6.d0*(-1.d0 + 2*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(3,1)=6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(3,2)=18.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t
    H_ss(3,2)=6.d0*(-1.d0 + 3.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(3,2)=18.d0*(-1.d0 + s)*s**2*(-1.d0 + 2.d0*t)
    H_st(3,3)=18.d0*(-1.d0 + s)*s*t*(-2.d0 + 3.d0*t)
    H_ss(3,3)=18.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)*t**2
    H_tt(3,3)=6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + 3.d0*t)
    H_st(3,4)=9.d0*s*(-2.d0 + 3.d0*s)*t*(-2.d0 + 3.d0*t)
    H_ss(3,4)=18.d0*(-1.d0 + 3.d0*s)*(-1.d0 + t)*t**2
    H_tt(3,4)=18.d0*(-1.d0 + s)*s**2*(-1.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (4)
    H_st(4,1)=-36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(4,1)=-6.d0*(-1.d0 + 2.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(4,1)=-6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(4,2)=-18.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*(-1.d0 + t)*t
    H_ss(4,2)=-6.d0*(-2.d0 + 3.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(4,2)=6.d0*(-1.d0 + s)**2*s*(3.d0 - 6.d0*t)
    H_st(4,3)=-18.d0*(-1.d0 + s)*s*t*(-2.d0 + 3.d0*t)
    H_ss(4,3)=-18.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)*t**2
    H_tt(4,3)=-6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1 + 3.d0*t)
    H_st(4,4)=-9.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*t*(-2.d0 + 3.d0*t)
    H_ss(4,4)=-18.d0*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t**2
    H_tt(4,4)=18.d0*(-1.d0 + s)**2*s*(1.d0 - 3.d0*t)
  ! --- QUINTIC
  else
    !---------------------------------------------------------- vertex (1) _ss
    H_ss(1,1) = 60.*s**2 *(1.-s)* (1.-t)**5 - 60.*s*(1.-s)**2 * (1.-t)**5 &
               + 300.*s**2 *(1.-s)*t*(1.-t)**4 - 300.*s*(1.-s)**2 *t*(1.-t)**4 &
               + 600.*s**2 *(1.-s)*t**2 * (1.-t)**3 - 600.*s*(1.-s)**2 * t**2 * (1.-t)**3
    H_ss(1,2) = -180.*s*(1.-s)**2 * (1.-t)**5 - 900.*s*(1.-s)**2 *t*(1.-t)**4 &
               + 120.*s**2 *(1.-s)*(1.-t)**5 + 600.*s**2 *(1.-s)*t*(1.-t)**4
    H_ss(1,3) = + 300.*s*(1.-s)**2 *t*(1.-t)**4 - 100.*(1.-s)**3 *t*(1.-t)**4 &
               + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3 - 400.*(1.-s)**3 *t**2 *(1.-t)**3
    H_ss(1,4) = -900.*s*(1.-s)**2 *t*(1.-t)**4 + 600.*s**2 *(1.-s)*t*(1.-t)**4 &
               - 3600.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 2400.*s**2 *(1.-s)*t**2 * (1.-t)**3
    H_ss(1,5) = 60.*s**2 *(1.-s)*(1.-t)**5 - 120.*s*(1.-s)**2 *(1.-t)**5 &
               + 20.*(1.-s)**3 *(1.-t)**5 + 300.*s**2 *(1.-s)*t*(1.-t)**4 &
               - 600.*s*(1.-s)**2 *t*(1.-t)**4 + 100.*(1.-s)**3 *t*(1.-t)**4
    H_ss(1,6) = + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3 - 200.*(1.-s)**3 *t**2 *(1.-t)**3
    H_ss(1,7) = 300.*s**2 *(1.-s)*t*(1.-t)**4 - 600.*s*(1.-s)**2 *t*(1.-t)**4 &
               + 100.*(1.-s)**3 *t*(1.-t)**4 + 1200.*s**2 *(1.-s)*t**2 *(1.-t)**3 &
               - 2400.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 400.*(1.-s)**3 *t**2 *(1.-t)**3
    H_ss(1,8) = -600.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 1200.*s**2 *(1.-s)*t**2 *(1.-t)**3 &
               - 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
    H_ss(1,9) = 600.*s**2 *(1.-s)*t**2 *(1.-t)**3 - 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3 &
               + 200.*(1.-s)**3 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (2) _ss
    H_ss(2,1) = -60.*s**2 *(1.-s)*(1.-t)**5 + 60.*s*(1.-s)**2 *(1.-t)**5 &
               - 300.*s**2 *(1.-s)*t*(1.-t)**4 + 300.*s*(1.-s)**2 *t*(1.-t)**4 &
               - 600.*s**2 *(1.-s)*t**2 *(1.-t)**3 + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3 
    H_ss(2,2) = - 180.*s**2*(1.-s) *(1.-t)**5 - 900.*s**2 *(1.-s)*t*(1.-t)**4 &
               + 120.*s*(1.-s)**2 *(1.-t)**5 + 600.*s*(1.-s)**2 *t*(1.-t)**4
    H_ss(2,3) = - 100.*s**3 *t*(1.-t)**4 + 300.*s**2 *(1.-s)*t*(1.-t)**4 &
               - 400.*s**3 *t**2 *(1.-t)**3 + 1200.*s**2 *(1.-s) *t**2 *(1.-t)**3
    H_ss(2,4) = - 900.*s**2 *(1.-s)*t*(1.-t)**4 + 600.*s*(1.-s)**2 *t*(1.-t)**4 &
               - 3600.*s**2 *(1.-s) *t**2 *(1.-t)**3 + 2400.*s*(1.-s)**2 *t**2 *(1.-t)**3
    H_ss(2,5) = 20.*s**3 *(1.-t)**5 - 120.*s**2 *(1.-s) *(1.-t)**5 &
               + 60.*s*(1.-s)**2 *(1.-t)**5 + 100.*s**3 *t*(1.-t)**4 &
               - 600.*s**2*(1.-s) *t*(1.-t)**4 + 300.*s*(1.-s)**2 *t*(1.-t)**4
    H_ss(2,6) = - 200.*s**3 *t**2 *(1.-t)**3 + 600.*s**2 *(1.-s) *t**2 *(1.-t)**3
    H_ss(2,7) = 100.*s**3 *t*(1.-t)**4 - 600.*s**2 *(1.-s)*t*(1.-t)**4 &
               + 300.*s*(1.-s)**2 *t*(1.-t)**4 + 400.*s**3 *t**2 *(1.-t)**3 &
               - 2400.*s**2 *(1.-s) *t**2 *(1.-t)**3 + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
    H_ss(2,8) = - 1800.*s**2 *(1.-s) *t**2 *(1.-t)**3 + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
    H_ss(2,9) = 200.*s**3 *t**2 *(1.-t)**3 - 1200.*s**2 *(1.-s) *t**2 *(1.-t)**3 &
               + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (3) _ss
    H_ss(3,1) = - 60.*s**2 *(1.-s)*t**5 + 60.*s*(1.-s)**2 *t**5 &
               - 300.*s**2 *(1.-s)*t**4 *(1.-t) + 300.*s*(1.-s)**2 *t**4 *(1.-t) &
               - 600.*s**2 *(1.-s)*t**3 *(1.-t)**2 + 600.*s*(1.-s)**2 *t**3 *(1.-t)**2 
    H_ss(3,2) = - 180.*s**2 *(1.-s) *t**5 - 900.*s**2 *(1.-s) *t**4 *(1.-t) &
               + 120.*s*(1.-s)**2 *t**5 + 600.*s*(1.-s)**2 *t**4 *(1.-t)
    H_ss(3,3) = - 100.*s**3 *t**4 *(1.-t) + 300.*s**2 *(1.-s) *t**4 *(1.-t) &
               - 400.*s**3 *t**3 *(1.-t)**2 + 1200.*s**2 *(1.-s) *t**3 *(1.-t)**2
    H_ss(3,4) = - 900.*s**2 *(1.-s) *t**4 *(1.-t) + 600.*s*(1.-s)**2 *t**4 *(1.-t) &
               - 3600.*s**2 *(1.-s)*t**3 *(1.-t)**2 + 2400.*s*(1.-s)**2 *t**3 *(1.-t)**2
    H_ss(3,5) = 20.*s**3 *t**5 - 120.*s**2 *(1.-s) *t**5 + 60.*s*(1.-s)**2 *t**5 &
               + 100.*s**3 *t**4 *(1.-t) - 600.*s**2 *(1.-s) *t**4 *(1.-t) &
               + 300.*s*(1.-s)**2 *t**4 *(1.-t)
    H_ss(3,6) = -200.*s**3 *t**3 *(1.-t)**2 + 600.*s**2 *(1.-s) *t**3 *(1.-t)**2
    H_ss(3,7) = 100.*s**3 *t**4 *(1.-t) - 600.*s**2 *(1.-s) *t**4 *(1.-t) &
               + 300.*s*(1.-s)**2 *t**4 *(1.-t) + 400.*s**3 *t**3 *(1.-t)**2 &
               - 2400.*s**2 *(1.-s) *t**3 *(1.-t)**2 + 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2 
    H_ss(3,8) = - 1800.*s**2 *(1.-s) *t**3 *(1.-t)**2 + 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2
    H_ss(3,9) = 200.*s**3 *t**3 *(1.-t)**2 - 1200.*s**2 *(1.-s) *t**3 *(1.-t)**2 &
               + 600.*s*(1.-s)**2 *t**3 *(1.-t)**2
    !---------------------------------------------------------- vertex (4) _ss
    H_ss(4,1) = + 60.*s**2 *(1.-s)*t**5 - 60.*s*(1.-s)**2 *t**5 &
               + 300.*s**2 *(1.-s)*t**4 *(1.-t) - 300.*s*(1.-s)**2 *t**4 *(1.-t) &
               + 600.*s**2 *(1.-s)*t**3 *(1.-t)**2 - 600.*s*(1.-s)**2 *t**3 *(1.-t)**2
    H_ss(4,2) = -60.*s*(1.-s)**2 *t**5 - 900.*s*(1.-s)**2 *t**4 *(1.-t) &
               + 120.*s**2 *(1.-s)*t**5 - 120.*s*(1.-s)**2 *t**5 &
               + 600.*s**2 *(1.-s)*t**4 *(1.-t)
    H_ss(4,3) = + 300.*s*(1.-s)**2 *t**4 *(1.-t) - 100.*(1.-s)**3 *t**4 *(1.-t) &
               + 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2 - 400.*(1.-s)**3 *t**3 *(1.-t)**2
    H_ss(4,4) = -900.*s*(1.-s)**2 *t**4 *(1.-t) + 600.*s**2 *(1.-s)*t**4 *(1.-t) &
               - 3600.*s*(1.-s)**2 *t**3 *(1.-t)**2 + 2400.*s**2 *(1.-s)*t**3 *(1.-t)**2
    H_ss(4,5) = 60.*s**2 *(1.-s)*t**5 - 120.*s*(1.-s)**2 *t**5 &
               + 20.*(1.-s)**3 *t**5 + 300.*s**2 *(1.-s)*t**4 *(1.-t) &
               - 600.*s*(1.-s)**2 *t**4 *(1.-t) + 100.*(1.-s)**3 *t**4 *(1.-t)
    H_ss(4,6) = + 600.*s*(1.-s)**2 *t**3 *(1.-t)**2 - 200.*(1.-s)**3 *t**3 *(1.-t)**2
    H_ss(4,7) = 300.*s**2 *(1.-s)*t**4 *(1.-t) - 600.*s*(1.-s)**2 *t**4 *(1.-t) &
               + 100.*(1.-s)**3 *t**4 *(1.-t) + 1200.*s**2 *(1.-s)*t**3 *(1.-t)**2 &
               - 2400.*s*(1.-s)**2 *t**3 *(1.-t)**2 + 400.*(1.-s)**3 *t**3 *(1.-t)**2
    H_ss(4,8) = -1800.*s*(1.-s)**2 *t**3 *(1.-t)**2 + 1200.*s**2 *(1.-s)*t**3 *(1.-t)**2
    H_ss(4,9) = 600.*s**2 *(1.-s)*t**3 *(1.-t)**2 - 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2 &
               + 200.*(1.-s)**3 *t**3 *(1.-t)**2
    !---------------------------------------------------------- vertex (1) _tt
    H_tt(1,1) = 60.*(1.-s)**5 * t**2 *(1.-t) - 60.*(1.-s)**5 * t*(1.-t)**2 &
               + 300.*s*(1.-s)**4 *t**2 *(1.-t) - 300.*s*(1.-s)**4 *t*(1.-t)**2 &
               + 600.*s**2 * (1.-s)**3 * t**2 *(1.-t) - 600.*s**2 * (1.-s)**3 * t*(1.-t)**2
    H_tt(1,2) = 300.*s*(1.-s)**4 *t*(1.-t)**2 - 100.*s*(1.-s)**4 *(1.-t)**3 &
               + 1200.*s**2 * (1.-s)**3 *t*(1.-t)**2 - 400.*s**2 * (1.-s)**3 *(1.-t)**3
    H_tt(1,3) = -180.*(1.-s)**5 *t*(1.-t)**2 - 900.*s*(1.-s)**4 *t*(1.-t)**2 &
               + 120.*(1.-s)**5 *t**2 *(1.-t) + 600.*s*(1.-s)**4 *t**2 *(1.-t)
    H_tt(1,4) = -900.*s*(1.-s)**4 *t*(1.-t)**2 - 3600.*s**2 * (1.-s)**3 *t*(1.-t)**2 &
               + 600.*s*(1.-s)**4 *t**2 *(1.-t) + 2400.*s**2 *(1.-s)**3 *t**2 * (1.-t)
    H_tt(1,5) = 600.*s**2 *(1.-s)**3 *t*(1.-t)**2 - 200.*s**2 *(1.-s)**3 *(1.-t)**3
    H_tt(1,6) = 60.*(1.-s)**5 *t**2 *(1.-t) - 120.*(1.-s)**5 *t*(1.-t)**2 &
               + 20.*(1.-s)**5 *(1.-t)**3 + 300.*s*(1.-s)**4 *t**2 *(1.-t) &
               - 600.*s*(1.-s)**4 *t*(1.-t)**2 + 100.*s*(1.-s)**4 *(1.-t)**3
    H_tt(1,7) = -1800.*s**2 *(1.-s)**3 *t*(1.-t)**2 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t)
    H_tt(1,8) = 300.*s*(1.-s)**4 *t**2 *(1.-t) - 600.*s*(1.-s)**4 *t*(1.-t)**2 &
               + 100.*s*(1.-s)**4 *(1.-t)**3 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t) &
               - 2400.*s**2 *(1.-s)**3 *t*(1.-t)**2 + 400.*s**2 *(1.-s)**3 *(1.-t)**3
    H_tt(1,9) = 600.*s**2 *(1.-s)**3 *t**2 *(1.-t) - 1200.*s**2 *(1.-s)**3 *t*(1.-t)**2 &
               + 200.*s**2 *(1.-s)**3 *(1.-t)**3
    !---------------------------------------------------------- vertex (2) _tt
    H_tt(2,1) = 60.*s**5 *t**2 *(1.-t) - 60.*s**5 *t*(1.-t)**2 &
               + 300.*s**4 *(1.-s) *t**2 *(1.-t) - 300.*s**4 *(1.-s) *t*(1.-t)**2 &
               + 600.*s**3 *(1.-s)**2 *t**2 *(1.-t) - 600.*s**3 *(1.-s)**2 *t*(1.-t)**2
    H_tt(2,2) = 300.*s**4 *(1.-s)*t*(1.-t)**2 - 100.*s**4 *(1.-s)*(1.-t)**3 &
               + 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2 - 400.*s**3 *(1.-s)**2 *(1.-t)**3
    H_tt(2,3) = -180.*s**5 *t*(1.-t)**2 - 900.*s**4 *(1.-s)*t*(1.-t)**2 &
               + 120.*s**5 *t**2 *(1.-t) + 600.*s**4 *(1.-s) *t**2 *(1.-t)
    H_tt(2,4) = -900.*s**4 *(1.-s)*t*(1.-t)**2 - 3600.*s**3 *(1.-s)**2 *t*(1.-t)**2 &
               + 600.*s**4 *(1.-s) *t**2 *(1.-t) + 2400.*s**3 *(1.-s)**2 *t**2 *(1.-t)
    H_tt(2,5) = 600.*s**3 *(1.-s)**2 *t*(1.-t)**2 - 200.*s**3 *(1.-s)**2 *(1.-t)**3
    H_tt(2,6) = 60.*s**5 *t**2 *(1.-t) - 120.*s**5 *t*(1.-t)**2 &
               + 20.*s**5 *(1.-t)**3 + 300.*s**4 *(1.-s) *t**2 *(1.-t) &
               - 600.*s**4 *(1.-s) *t*(1.-t)**2 + 100.*s**4 *(1.-s) *(1.-t)**3
    H_tt(2,7) = -1800.*s**3 *(1.-s)**2 *t*(1.-t)**2 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t) 
    H_tt(2,8) = 300.*s**4 *(1.-s) *t**2 *(1.-t) - 600.*s**4 *(1.-s) *t*(1.-t)**2 &
               + 100.*s**4 *(1.-s) *(1.-t)**3 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t) &
               - 2400.*s**3 *(1.-s)**2 *t*(1.-t)**2 + 400.*s**3 *(1.-s)**2 *(1.-t)**3
    H_tt(2,9) = 600.*s**3 *(1.-s)**2 *t**2 *(1.-t) - 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2 &
               + 200.*s**3 *(1.-s)**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (3) _tt
    H_tt(3,1) = -60.*s**5 *t**2 *(1.-t) + 60.*s**5 *t*(1.-t)**2 &
               - 300.*s**4 *(1.-s) *t**2 *(1.-t) + 300.*s**4 *(1.-s) *t*(1.-t)**2 &
               - 600.*s**3 *(1.-s)**2 *t**2 *(1.-t) + 600.*s**3 *(1.-s)**2 *t*(1.-t)**2 
    H_tt(3,2) = -100.*s**4 *(1.-s) *t**3 + 300.*s**4 *(1.-s) *t**2 *(1.-t) &
               - 400.*s**3 *(1.-s)**2 *t**3 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t)
    H_tt(3,3) = - 180.*s**5 *t**2 *(1.-t) - 900.*s**4 *(1.-s) *t**2 *(1.-t) &
               + 120.*s**5 *t*(1.-t)**2 + 600.*s**4 *(1.-s) *t*(1.-t)**2
    H_tt(3,4) = - 900.*s**4 *(1.-s) *t**2 *(1.-t) - 3600.*s**3 *(1.-s)**2 *t**2 *(1.-t) &
               + 600.*s**4 *(1.-s) *t*(1.-t)**2 + 2400.*s**3 *(1.-s)**2 *t*(1.-t)**2
    H_tt(3,5) = - 200.*s**3 *(1.-s)**2 *t**3 + 600.*s**3 *(1.-s)**2 *t**2 *(1.-t)
    H_tt(3,6) = 20.*s**5 *t**3 - 120.*s**5 *t**2 *(1.-t) &
               + 60.*s**5 *t*(1.-t)**2 + 100.*s**4 *(1.-s) *t**3 &
               - 600.*s**4 *(1.-s) *t**2 *(1.-t) + 300.*s**4 *(1.-s) *t*(1.-t)**2
    H_tt(3,7) = - 1800.*s**3 *(1.-s)**2 *t**2 *(1.-t) + 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2 
    H_tt(3,8) = 100.*s**4 *(1.-s) *t**3 - 600.*s**4 *(1.-s) *t**2 *(1.-t) &
               + 300.*s**4 *(1.-s) *t*(1.-t)**2 + 400.*s**3 *(1.-s)**2 *t**3 &
               - 2400.*s**3 *(1.-s)**2 *t**2 *(1.-t) + 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2
    H_tt(3,9) = 200.*s**3 *(1.-s)**2 *t**3 - 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t) &
               + 600.*s**3 *(1.-s)**2 *t*(1.-t)**2
    !---------------------------------------------------------- vertex (4) _tt
    H_tt(4,1) = - 60.*(1.-s)**5 *t**2 *(1.-t) + 60.*(1.-s)**5 *t*(1.-t)**2 &
               - 300.*s*(1.-s)**4 *t**2 *(1.-t) + 300.*s*(1.-s)**4 *t*(1.-t)**2 &
               - 600.*s**2 *(1.-s)**3 *t**2 *(1.-t) + 600.*s**2 *(1.-s)**3 *t*(1.-t)**2
    H_tt(4,2) = - 100.*s*(1.-s)**4 *t**3 + 300.*s*(1.-s)**4 *t**2 *(1.-t) &
               - 400.*s**2 *(1.-s)**3 *t**3 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t)
    H_tt(4,3) = - 180.*(1.-s)**5 *t**2 *(1.-t) - 900.*s*(1.-s)**4 *t**2 *(1.-t) &
               + 120.*(1.-s)**5 *t*(1.-t)**2 + 600.*s*(1.-s)**4 *t*(1.-t)**2
    H_tt(4,4) = - 900.*s*(1.-s)**4 *t**2 *(1.-t) - 3600.*s**2 *(1.-s)**3 *t**2 *(1.-t) &
               + 600.*s*(1.-s)**4 *t*(1.-t)**2 + 2400.*s**2 *(1.-s)**3 *t*(1.-t)**2
    H_tt(4,5) = -200.*s**2 *(1.-s)**3 *t**3 + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)
    H_tt(4,6) = 20.*(1.-s)**5 *t**3 - 120.*(1.-s)**5 *t**2 *(1.-t) &
               + 60.*(1.-s)**5 *t*(1.-t)**2 + 100.*s*(1.-s)**4 *t**3 &
               - 600.*s*(1.-s)**4 *t**2 *(1.-t) + 300.*s*(1.-s)**4 *t*(1.-t)**2
    H_tt(4,7) = - 1800.*s**2 *(1.-s)**3 *t**2 *(1.-t) + 1200.*s**2 *(1.-s)**3 *t*(1.-t)**2
    H_tt(4,8) = 100.*s*(1.-s)**4 *t**3 - 600.*s*(1.-s)**4 *t**2 *(1.-t) &
               + 300.*s*(1.-s)**4 *t*(1.-t)**2 + 400.*s**2 *(1.-s)**3 *t**3 &
               - 2400.*s**2 *(1.-s)**3 *t**2 *(1.-t) + 1200.*s**2 *(1.-s)**3 *t*(1.-t)**2
    H_tt(4,9) = 200.*s**2 *(1.-s)**3 *t**3 - 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t) &
               + 600.*s**2 *(1.-s)**3 *t*(1.-t)**2
    !---------------------------------------------------------- vertex (1) _st
    H_st(1,1) = 900.*s**2 * (1.-s)**2 * t**2 * (1.-t)**2
    H_st(1,2) = - 400.*s*(1.-s)**3 *t*(1.-t)**3 - 100.*(1.-s)**4 *t*(1.-t)**3 &
               + 1200.*s**2 * (1.-s)**2 *t*(1.-t)**3
    H_st(1,3) = -400.*s*(1.-s)**3 *t*(1.-t)**3 - 100.*s*(1.-s)**3 *(1.-t)**4 &
               + 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(1,4) = 400.*s*(1.-s)**3 *t*(1.-t)**3 + 100.*s*(1.-s)**3 *(1.-t)**4 &
               + 100.*(1.-s)**4 *t*(1.-t)**3 + 25.*(1.-s)**4 *(1.-t)**4 &
               - 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 300.*s**2 * (1.-s)**2 *(1.-t)**4 &
               - 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2 - 300.*(1.-s)**4 *t**2 *(1.-t)**2 &
               + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(1,5) = + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 400.*s *(1.-s)**3 *t*(1.-t)**3
    H_st(1,6) = 600.*s*(1.-s)**3 *t**2 *(1.-t)**2 - 400.*s*(1.-s)**3 *t*(1.-t)**3
    H_st(1,7) = -600.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 150.*s**2 *(1.-s)**2 *(1.-t)**4 &
               + 400.*s *(1.-s)**3 *t*(1.-t)**3 + 100.*s *(1.-s)**3 *(1.-t)**4 &
               + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 1200.*s *(1.-s)**3 *t**2 *(1.-t)**2
    H_st(1,8) = -600.*s*(1.-s)**3 *t**2 *(1.-t)**2 + 400.*s*(1.-s)**3 *t*(1.-t)**3 &
               - 150.*(1.-s)**4 *t**2 *(1.-t)**2 + 100.*(1.-s)**4 *t*(1.-t)**3 &
               + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(1,9) = 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 &
               - 600.*s *(1.-s)**3 *t**2 *(1.-t)**2 + 400.*s *(1.-s)**3 *t*(1.-t)**3
    !---------------------------------------------------------- vertex (2) _st
    H_st(2,1) = - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,2) = + 100.*s**4 *t*(1.-t)**3 + 400.*s**3 *(1.-s)*t*(1.-t)**3 &
               - 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(2,3) = 400.*s**3 *(1.-s)*t*(1.-t)**3 + 100.*s**3 *(1.-s)*(1.-t)**4 &
               - 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2
    H_st(2,4) = -100.*s**4 *t*(1.-t)**3 - 25.*s**4 *(1.-t)**4 - 400.*s**3 *(1.-s)*t*(1.-t)**3 &
               - 100.*s**3 *(1.-s)*(1.-t)**4 + 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3 &
               + 300.*s**2 *(1.-s)**2 *(1.-t)**4 + 300.*s**4 *t**2 *(1.-t)**2 &
               + 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,5) = + 400.*s**3 *(1.-s) *t*(1.-t)**3 - 600.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(2,6) = -600.*s**3 *(1.-s) *t**2 *(1.-t)**2 + 400.*s**3 *(1.-s) *t*(1.-t)**3
    H_st(2,7) = -400.*s**3 *(1.-s)*t*(1.-t)**3 - 100.*s**3 *(1.-s)*(1.-t)**4 &
               + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 + 150.*s**2 *(1.-s)**2 *(1.-t)**4 &
               + 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,8) = 150.*s**4 *t**2 *(1.-t)**2 - 100.*s**4 *t*(1.-t)**3 &
               + 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 400.*s**3 *(1.-s) *t*(1.-t)**3 &
               - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 + 1200.*s**2 *(1.-s)**2 *t*(1.-t)**3
    H_st(2,9) = 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 - 400.*s**3 *(1.-s) *t*(1.-t)**3 &
               - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3
    !---------------------------------------------------------- vertex (3) _st
    H_st(3,1) = + 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 
    H_st(3,2) = - 100.*s**4 *t**3 *(1.-t) - 400.*s**3 *(1.-s) *t**3 *(1.-t) &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(3,3) = - 100.*s**3 *(1.-s) *t**4 - 400.*s**3 *(1.-s) *t**3 *(1.-t) &
               + 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2
    H_st(3,4) = 25.*s**4 *t**4 + 100.*s**4 *t**3 *(1.-t) + 100.*s**3 *(1.-s) *t**4 &
               + 400.*s**3 *(1.-s) *t**3 *(1.-t) - 300.*s**2 *(1.-s)**2 *t**4 &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 300.*s**4 *t**2 *(1.-t)**2 &
               - 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(3,5) = - 400.*s**3 *(1.-s) *t**3 *(1.-t) + 600.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(3,6) = -400.*s**3 *(1.-s) *t**3 *(1.-t) + 600.*s**3 *(1.-s) *t**2 *(1.-t)**2
    H_st(3,7) = 100.*s**3 *(1.-s) *t**4 + 400.*s**3 *(1.-s) *t**3 *(1.-t) &
               - 150.*s**2 *(1.-s)**2 *t**4 - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) &
               - 1200.*s**3 *(1.-s) *t**2 *(1.-t)**2 + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 
    H_st(3,8) = 100.*s**4 *t**3 *(1.-t) - 150.*s**4 *t**2 *(1.-t)**2 &
               + 400.*s**3 *(1.-s) *t**3 *(1.-t) - 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(3,9) = 400.*s**3 *(1.-s) *t**3 *(1.-t) - 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 &
               - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    !---------------------------------------------------------- vertex (4) _st
    H_st(4,1) = - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(4,2) = + 400.*s*(1.-s)**3 *t**3 *(1.-t) + 100.*(1.-s)**4 *t**3 *(1.-t) &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(4,3) = + 100.*s*(1.-s)**3 *t**4 + 400.*s*(1.-s)**3 *t**3 *(1.-t) &
               - 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,4) = -100.*s*(1.-s)**3 *t**4 - 400.*s*(1.-s)**3 *t**3 *(1.-t) - 25.*(1.-s)**4 *t**4 &
               - 100.*(1.-s)**4 *t**3 *(1.-t) + 300.*s**2 *(1.-s)**2 *t**4 &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2 &
               + 300.*(1.-s)**4 *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(4,5) = - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 400.*s *(1.-s)**3 *t**3 *(1.-t)
    H_st(4,6) = 400.*s*(1.-s)**3 *t**3 *(1.-t) - 600.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,7) = 150.*s**2 *(1.-s)**2 *t**4 - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) &
               - 100.*s *(1.-s)**3 *t**4 + 400.*s *(1.-s)**3 *t**3 *(1.-t) &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 &
               - 800.*s *(1.-s)**3 *t**3 *(1.-t) + 1200.*s *(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,8) = -400.*s*(1.-s)**3 *t**3 *(1.-t) + 600.*s*(1.-s)**3 *t**2 *(1.-t)**2 &
               - 100.*(1.-s)**4 *t**3 *(1.-t) + 150.*(1.-s)**4 *t**2 *(1.-t)**2 &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(4,9) = 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 &
               - 400.*s *(1.-s)**3 *t**3 *(1.-t) + 600.*s *(1.-s)**3 *t**2 *(1.-t)**2
  endif
end subroutine basisfunctions_2D_2
  
!> Basisfunctions with second derivatives in 2D and transposed matrix for 
!> better vectorisation
pure subroutine basisfunctions_2D_2_T(s, t, H, H_s, H_t, H_st, H_ss, H_tt)
  implicit none
  real*8, intent(in)  :: s                  !< s-coordinate in the element [0,1]
  real*8, intent(in)  :: t                  !< t-coordinate in the element [0,1]
  real*8, intent(out) :: H   (n_order+1,4)  !< Basis functions
  real*8, intent(out) :: H_s (n_order+1,4)  !< Basis functions derived with respect to s
  real*8, intent(out) :: H_t (n_order+1,4)  !< Basis functions derived with respect to t
  real*8, intent(out) :: H_st(n_order+1,4)  !< Basis functions derived with respect to s and t
  real*8, intent(out) :: H_ss(n_order+1,4)  !< Basis functions derived two times with respect to s
  real*8, intent(out) :: H_tt(n_order+1,4)  !< Basis functions derived two times with respect to t
  
  call basisfunctions_2D_1_T(s, t, H, H_s, H_t)
  
  ! --- CUBIC
  if (n_order .eq. 3) then
    !---------------------------------------------------------- vertex (1)
    H_st(1,1)=36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(1,1)=6.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_tt(1,1)=6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(2,1)=18.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*(-1.d0 + t)*t
    H_ss(2,1)=6.d0*(-2.d0 + 3.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_tt(2,1)=18.d0*(-1.d0 + s)**2*s*(-1.d0 + 2.d0*t)
    H_st(3,1)=18.d0*(-1.d0 + s)*s*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(3,1)=18.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)**2*t
    H_tt(3,1)=6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-2.d0 + 3.d0*t)
    H_st(4,1)=9.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(4,1)=18.d0*(-2.d0 + 3.d0*s)*(-1.d0 + t)**2*t
    H_tt(4,1)=18.d0*(-1.d0 + s)**2*s*(-2.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (2)
    H_st(1,2)=-36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(1,2)=-6.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_tt(1,2)=-6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(2,2)=-18.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t
    H_ss(2,2)=-6.d0*(-1.d0 + 3.d0*s)*(-1.d0 + t)**2*(1 + 2.d0*t)
    H_tt(2,2)=-18.d0*(-1.d0 + s)*s**2*(-1.d0 + 2.d0*t)
    H_st(3,2)=-18.d0*(-1.d0 + s)*s*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(3,2)=6.d0*(3.d0 - 6.d0*s)*(-1.d0 + t)**2*t
    H_tt(3,2)=-6.d0*s**2*(-3.d0 + 2.d0*s)*(-2.d0 + 3.d0*t)
    H_st(4,2)=-9.d0*s*(-2.d0 + 3.d0*s)*(1.d0 - 4.d0*t + 3.d0*t**2)
    H_ss(4,2)=18.d0*(1.d0 - 3.d0*s)*(-1.d0 + t)**2*t
    H_tt(4,2)=-18.d0*(-1.d0 + s)*s**2*(-2.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (3)
    H_st(1,3)=36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(1,3)=6.d0*(-1.d0 + 2*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(1,3)=6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(2,3)=18.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t
    H_ss(2,3)=6.d0*(-1.d0 + 3.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(2,3)=18.d0*(-1.d0 + s)*s**2*(-1.d0 + 2.d0*t)
    H_st(3,3)=18.d0*(-1.d0 + s)*s*t*(-2.d0 + 3.d0*t)
    H_ss(3,3)=18.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)*t**2
    H_tt(3,3)=6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + 3.d0*t)
    H_st(4,3)=9.d0*s*(-2.d0 + 3.d0*s)*t*(-2.d0 + 3.d0*t)
    H_ss(4,3)=18.d0*(-1.d0 + 3.d0*s)*(-1.d0 + t)*t**2
    H_tt(4,3)=18.d0*(-1.d0 + s)*s**2*(-1.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (4)
    H_st(1,4)=-36.d0*(-1.d0 + s)*s*(-1.d0 + t)*t
    H_ss(1,4)=-6.d0*(-1.d0 + 2.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(1,4)=-6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + 2.d0*t)
    H_st(2,4)=-18.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*(-1.d0 + t)*t
    H_ss(2,4)=-6.d0*(-2.d0 + 3.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_tt(2,4)=6.d0*(-1.d0 + s)**2*s*(3.d0 - 6.d0*t)
    H_st(3,4)=-18.d0*(-1.d0 + s)*s*t*(-2.d0 + 3.d0*t)
    H_ss(3,4)=-18.d0*(-1.d0 + 2.d0*s)*(-1.d0 + t)*t**2
    H_tt(3,4)=-6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1 + 3.d0*t)
    H_st(4,4)=-9.d0*(1.d0 - 4.d0*s + 3.d0*s**2)*t*(-2.d0 + 3.d0*t)
    H_ss(4,4)=-18.d0*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t**2
    H_tt(4,4)=18.d0*(-1.d0 + s)**2*s*(1.d0 - 3.d0*t)
  ! --- QUINTIC
  else
    !---------------------------------------------------------- vertex (1) _ss
    H_ss(1,1) = 60.*s**2 *(1.-s)* (1.-t)**5 - 60.*s*(1.-s)**2 * (1.-t)**5 &
               + 300.*s**2 *(1.-s)*t*(1.-t)**4 - 300.*s*(1.-s)**2 *t*(1.-t)**4 &
               + 600.*s**2 *(1.-s)*t**2 * (1.-t)**3 - 600.*s*(1.-s)**2 * t**2 * (1.-t)**3
    H_ss(2,1) = -180.*s*(1.-s)**2 * (1.-t)**5 - 900.*s*(1.-s)**2 *t*(1.-t)**4 &
               + 120.*s**2 *(1.-s)*(1.-t)**5 + 600.*s**2 *(1.-s)*t*(1.-t)**4
    H_ss(3,1) = + 300.*s*(1.-s)**2 *t*(1.-t)**4 - 100.*(1.-s)**3 *t*(1.-t)**4 &
               + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3 - 400.*(1.-s)**3 *t**2 *(1.-t)**3
    H_ss(4,1) = -900.*s*(1.-s)**2 *t*(1.-t)**4 + 600.*s**2 *(1.-s)*t*(1.-t)**4 &
               - 3600.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 2400.*s**2 *(1.-s)*t**2 * (1.-t)**3
    H_ss(5,1) = 60.*s**2 *(1.-s)*(1.-t)**5 - 120.*s*(1.-s)**2 *(1.-t)**5 &
               + 20.*(1.-s)**3 *(1.-t)**5 + 300.*s**2 *(1.-s)*t*(1.-t)**4 &
               - 600.*s*(1.-s)**2 *t*(1.-t)**4 + 100.*(1.-s)**3 *t*(1.-t)**4
    H_ss(6,1) = + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3 - 200.*(1.-s)**3 *t**2 *(1.-t)**3
    H_ss(7,1) = 300.*s**2 *(1.-s)*t*(1.-t)**4 - 600.*s*(1.-s)**2 *t*(1.-t)**4 &
               + 100.*(1.-s)**3 *t*(1.-t)**4 + 1200.*s**2 *(1.-s)*t**2 *(1.-t)**3 &
               - 2400.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 400.*(1.-s)**3 *t**2 *(1.-t)**3
    H_ss(8,1) = -600.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 1200.*s**2 *(1.-s)*t**2 *(1.-t)**3 &
               - 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
    H_ss(9,1) = 600.*s**2 *(1.-s)*t**2 *(1.-t)**3 - 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3 &
               + 200.*(1.-s)**3 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (2) _ss
