               + 400.*s**3 *(1.-s) *t**3 *(1.-t) - 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(9,3) = 400.*s**3 *(1.-s) *t**3 *(1.-t) - 600.*s**3 *(1.-s) *t**2 *(1.-t)**2 &
               - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    !---------------------------------------------------------- vertex (4) _st
    H_st(1,4) = - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(2,4) = + 400.*s*(1.-s)**3 *t**3 *(1.-t) + 100.*(1.-s)**4 *t**3 *(1.-t) &
               - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)
    H_st(3,4) = + 100.*s*(1.-s)**3 *t**4 + 400.*s*(1.-s)**3 *t**3 *(1.-t) &
               - 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(4,4) = -100.*s*(1.-s)**3 *t**4 - 400.*s*(1.-s)**3 *t**3 *(1.-t) - 25.*(1.-s)**4 *t**4 &
               - 100.*(1.-s)**4 *t**3 *(1.-t) + 300.*s**2 *(1.-s)**2 *t**4 &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2 &
               + 300.*(1.-s)**4 *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(5,4) = - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) + 400.*s *(1.-s)**3 *t**3 *(1.-t)
    H_st(6,4) = 400.*s*(1.-s)**3 *t**3 *(1.-t) - 600.*s*(1.-s)**3 *t**2 *(1.-t)**2
    H_st(7,4) = 150.*s**2 *(1.-s)**2 *t**4 - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) &
               - 100.*s *(1.-s)**3 *t**4 + 400.*s *(1.-s)**3 *t**3 *(1.-t) &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 &
               - 800.*s *(1.-s)**3 *t**3 *(1.-t) + 1200.*s *(1.-s)**3 *t**2 *(1.-t)**2
    H_st(8,4) = -400.*s*(1.-s)**3 *t**3 *(1.-t) + 600.*s*(1.-s)**3 *t**2 *(1.-t)**2 &
               - 100.*(1.-s)**4 *t**3 *(1.-t) + 150.*(1.-s)**4 *t**2 *(1.-t)**2 &
               + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
    H_st(9,4) = 600.*s**2 *(1.-s)**2 *t**3 *(1.-t) - 900.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 &
               - 400.*s *(1.-s)**3 *t**3 *(1.-t) + 600.*s *(1.-s)**3 *t**2 *(1.-t)**2
  endif
end subroutine basisfunctions_2D_2_T
  
pure subroutine basisfunctions3(s, t, H, H_s, H_t)
  implicit none
  real*8, intent(in)  :: s                  !< s-coordinate in the element
  real*8, intent(in)  :: t                  !< t-coordinate in the element
  real*8, intent(out) :: H  (4,n_order+1)   !< Basis functions
  real*8, intent(out) :: H_s(4,n_order+1)   !< Basis functions derived with respect to s
  real*8, intent(out) :: H_t(4,n_order+1)   !< Basis functions derived with respect to t
  
  ! --- CUBIC
  if (n_order .eq. 3) then
    !---------------------------------------------------------- vertex (1)
    H(1,1)   =(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_s(1,1) =6.d0*(-1.d0 + s)*s*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_t(1,1) =6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + t)*t
    H(1,2)   =3.d0*(-1.d0 + s)**2*s*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_s(1,2) =3.d0*(-1.d0 + s)*(-1.d0 + 3.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_t(1,2) =18.d0*(-1.d0 + s)**2*s*(-1.d0 + t)*t
    H(1,3)   =3.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + t)**2*t
    H_s(1,3) =18.d0*(-1.d0 + s)*s*(-1.d0 + t)**2*t
    H_t(1,3) =3.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + t)*(-1.d0 + 3.d0*t)
    H(1,4)   =9.d0*(-1.d0 + s)**2*s*(-1.d0 + t)**2*t
    H_s(1,4) =9.d0*(-1.d0 + s)*(-1.d0 + 3.d0*s)*(-1.d0 + t)**2*t
    H_t(1,4) =9.d0*(-1.d0 + s)**2*s*(-1.d0 + t)*(-1.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (2)
    H(2,1)   =-(s**2*(-3.d0 + 2.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t))
    H_s(2,1) =-6.d0*(-1.d0 + s)*s*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_t(2,1) =-6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + t)*t
    H(2,2)   =-3.d0*(-1.d0 + s)*s**2*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_s(2,2) =-3.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)**2*(1.d0 + 2.d0*t)
    H_t(2,2) =-18.d0*(-1.d0 + s)*s**2*(-1.d0 + t)*t
    H(2,3)   =-3.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + t)**2*t
    H_s(2,3) =-18.d0*(-1.d0 + s)*s*(-1.d0 + t)**2*t
    H_t(2,3) =3.d0*s**2*(-3.d0 + 2.d0*s)*(1.d0 - 3.d0*t)*(-1.d0 + t)
    H(2,4)   =-9.d0*(-1.d0 + s)*s**2*(-1.d0 + t)**2*t
    H_s(2,4) =-9.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)**2*t
    H_t(2,4) =9.d0*(-1.d0 + s)*s**2*(1.d0 - 3.d0*t)*(-1.d0 + t)
    !---------------------------------------------------------- vertex (3)
    H(3,1)   =s**2*(-3.d0 + 2.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_s(3,1) =6.d0*(-1.d0 + s)*s*t**2*(-3.d0 + 2.d0*t)
    H_t(3,1) =6.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + t)*t
    H(3,2)   =3.d0*(-1.d0 + s)*s**2*t**2*(-3.d0 + 2.d0*t)
    H_s(3,2) =3.d0*s*(-2 + 3.d0*s)*t**2*(-3.d0 + 2.d0*t)
    H_t(3,2) =18.d0*(-1.d0 + s)*s**2*(-1.d0 + t)*t
    H(3,3)   =3.d0*s**2*(-3.d0 + 2.d0*s)*(-1.d0 + t)*t**2
    H_s(3,3) =18.d0*(-1.d0 + s)*s*(-1.d0 + t)*t**2
    H_t(3,3) =3.d0*s**2*(-3.d0 + 2.d0*s)*t*(-2.d0 + 3.d0*t)
    H(3,4)   =9.d0*(-1.d0 + s)*s**2*(-1.d0 + t)*t**2
    H_s(3,4) =9.d0*s*(-2.d0 + 3.d0*s)*(-1.d0 + t)*t**2
    H_t(3,4) =9.d0*(-1.d0 + s)*s**2*t*(-2.d0 + 3.d0*t)
    !---------------------------------------------------------- vertex (4)
    H(4,1)   =-((-1.d0 + s)**2*(1.d0 + 2.d0*s)*t**2*(-3.d0 + 2.d0*t))
    H_s(4,1) =-6.d0*(-1.d0 + s)*s*t**2*(-3.d0 + 2.d0*t)
    H_t(4,1) =-6.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + t)*t
    H(4,2)   =-3.d0*(-1.d0 + s)**2*s*t**2*(-3.d0 + 2.d0*t)
    H_s(4,2) =3.d0*(1.d0 - 3*s)*(-1.d0 + s)*t**2*(-3.d0 + 2.d0*t)
    H_t(4,2) =-18.d0*(-1.d0 + s)**2*s*(-1.d0 + t)*t
    H(4,3)   =-3.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*(-1.d0 + t)*t**2
    H_s(4,3) =-18.d0*(-1.d0 + s)*s*(-1.d0 + t)*t**2
    H_t(4,3) =-3.d0*(-1.d0 + s)**2*(1.d0 + 2.d0*s)*t*(-2.d0 + 3.d0*t)
    H(4,4)   =-9.d0*(-1.d0 + s)**2*s*(-1.d0 + t)*t**2
    H_s(4,4) =9.d0*(1.d0 - 3.d0*s)*(-1.d0 + s)*(-1.d0 + t)*t**2
    H_t(4,4) =-9.d0*(-1.d0 + s)**2*s*t*(-2.d0 + 3.d0*t)
  ! --- QUINTIC
  else
    !---------------------------------------------------------- vertex (1)
    H(1,1) = (1.-s)**5 * (1.-t)**5 + 5.*s*(1.-s)**4 * (1.-t)**5 &
            + 5.*(1.-s)**5 * t*(1.-t)**4 + 25.*s*(1.-s)**4 * t*(1.-t)**4 &
            + 10.*s**2 * (1.-s)**3 * (1.-t)**5 + 10.*(1.-s)**5 * t**2 * (1.-t)**3 &
            + 50.*s**2 * (1.-s)**3 *t*(1.-t)**4 + 50.*s*(1.-s)**4 *t**2 * (1.-t)**3 &
            + 100.*s**2 * (1.-s)**3 * t**2 * (1.-t)**3
    H(1,2) = 5.*s*(1.-s)**4 * (1.-t)**5 + 25.*s*(1.-s)**4 *t*(1.-t)**4 &
            + 20.*s**2 * (1.-s)**3 * (1.-t)**5 + 100.*s**2 * (1.-s)**3 *t*(1.-t)**4
    H(1,3) = 5.*(1.-s)**5 *t*(1.-t)**4 + 25.*s*(1.-s)**4 *t*(1.-t)**4 &
            + 20.*(1.-s)**5 *t**2 *(1.-t)**3 + 100.*s*(1.-s)**4 *t**2 *(1.-t)**3
    H(1,4) = 25.*s*(1.-s)**4 *t*(1.-t)**4 + 100.*s**2 * (1.-s)**3 *t*(1.-t)**4 &
            + 100.*s*(1.-s)**4 *t**2 *(1.-t)**3 + 400.*s**2 *(1.-s)**3 *t**2 * (1.-t)**3
    H(1,5) = 10.*s**2 *(1.-s)**3 *(1.-t)**5 + 50.*s**2 *(1.-s)**3 *t*(1.-t)**4
    H(1,6) = 10.*(1.-s)**5 *t**2 *(1.-t)**3 + 50.*s*(1.-s)**4 *t**2 *(1.-t)**3
    H(1,7) = 50.*s**2 *(1.-s)**3 *t*(1.-t)**4 + 200.*s**2 *(1.-s)**3 *t**2 *(1.-t)**3
    H(1,8) = 50.*s*(1.-s)**4 *t**2 *(1.-t)**3 + 200.*s**2 *(1.-s)**3 *t**2 *(1.-t)**3
    H(1,9) = 100.*s**2 *(1.-s)**3 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (2)
    H(2,1) = s**5 *(1.-t)**5 + 5.*s**4*(1.-s) *(1.-t)**5 &
            + 5.*s**5 *t*(1.-t)**4 + 25.*s**4 *(1.-s)*t*(1.-t)**4 &
            + 10.*s**3 *(1.-s)**2 *(1.-t)**5 + 10.*s**5 *t**2 *(1.-t)**3 &
            + 50.*s**3 *(1.-s)**2 *t*(1.-t)**4 + 50.*s**4 *(1.-s) *t**2 *(1.-t)**3 &
            + 100.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3 
    H(2,2) = 5.*s**4*(1.-s) *(1.-t)**5 + 25.*s**4 *(1.-s)*t*(1.-t)**4 &
            + 20.*s**3 *(1.-s)**2 *(1.-t)**5 + 100.*s**3 *(1.-s)**2 *t*(1.-t)**4
    H(2,3) = 5.*s**5 *t*(1.-t)**4 + 25.*s**4 *(1.-s)*t*(1.-t)**4 &
            + 20.*s**5 *t**2 *(1.-t)**3 + 100.*s**4 *(1.-s) *t**2 *(1.-t)**3
    H(2,4) = 25.*s**4 *(1.-s)*t*(1.-t)**4 + 100.*s**3 *(1.-s)**2 *t*(1.-t)**4 &
            + 100.*s**4 *(1.-s) *t**2 *(1.-t)**3 + 400.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
    H(2,5) = 10.*s**3 *(1.-s)**2 *(1.-t)**5 + 50.*s**3 *(1.-s)**2 *t*(1.-t)**4
    H(2,6) = 10.*s**5 *t**2 *(1.-t)**3 + 50.*s**4 *(1.-s) *t**2 *(1.-t)**3
    H(2,7) = 50.*s**3 *(1.-s)**2 *t*(1.-t)**4 + 200.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
    H(2,8) = 50.*s**4 *(1.-s) *t**2 *(1.-t)**3 + 200.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
    H(2,9) = 100.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (3)
    H(3,1) = s**5 *t**5 + 5.*s**4 *(1.-s)*t**5 + 5.*s**5 *t**4 *(1.-t) &
            + 25.*s**4 *(1.-s) *t**4 *(1.-t) + 10.*s**3 *(1.-s)**2 *t**5 &
            + 10.*s**5 *t**3 *(1.-t)**2 + 50.*s**3 *(1.-s)**2 *t**4 *(1.-t) &
            + 50.*s**4 *(1.-s) *t**3 *(1.-t)**2 + 100.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2 
    H(3,2) = 5.*s**4 *(1.-s) *t**5 + 25.*s**4 *(1.-s) *t**4 *(1.-t) &
            + 20.*s**3 *(1.-s)**2 *t**5 + 100.*s**3 *(1.-s)**2 *t**4 *(1.-t)
    H(3,3) = 5.*s**5 *t**4 *(1.-t) + 25.*s**4 *(1.-s) *t**4 *(1.-t) &
            + 20.*s**5 *t**3 *(1.-t)**2 + 100.*s**4 *(1.-s) *t**3 *(1.-t)**2
    H(3,4) = 25.*s**4 *(1.-s) *t**4 *(1.-t) + 100.*s**3 *(1.-s)**2 *t**4 *(1.-t) &
            + 100.*s**4 *(1.-s) *t**3 *(1.-t)**2 + 400.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2
    H(3,5) = 10.*s**3 *(1.-s)**2 *t**5 + 50.*s**3 *(1.-s)**2 *t**4 *(1.-t)
    H(3,6) = 10.*s**5 *t**3 *(1.-t)**2 + 50.*s**4 *(1.-s) *t**3 *(1.-t)**2
    H(3,7) = 50.*s**3 *(1.-s)**2 *t**4 *(1.-t) + 200.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2 
    H(3,8) = 50.*s**4 *(1.-s) *t**3 *(1.-t)**2 + 200.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2
    H(3,9) = 100.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2
    !---------------------------------------------------------- vertex (4)
    H(4,1) = (1.-s)**5 *t**5 + 5.*s*(1.-s)**4 *t**5 &
            + 5.*(1.-s)**5 *t**4 *(1.-t) + 25.*s*(1.-s)**4 *t**4 *(1.-t) &
            + 10.*s**2 *(1.-s)**3 *t**5 + 10.*(1.-s)**5 *t**3 *(1.-t)**2 &
            + 50.*s**2 *(1.-s)**3 *t**4 *(1.-t) + 50.*s*(1.-s)**4 *t**3 *(1.-t)**2 &
            + 100.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
    H(4,2) = 5.*s*(1.-s)**4 *t**5 + 25.*s*(1.-s)**4 *t**4 *(1.-t) &
            + 20.*s**2 *(1.-s)**3 *t**5 + 100.*s**2 *(1.-s)**3 *t**4 *(1.-t)
    H(4,3) = 5.*(1.-s)**5 *t**4 *(1.-t) + 25.*s*(1.-s)**4 *t**4 *(1.-t) &
            + 20.*(1.-s)**5 *t**3 *(1.-t)**2 + 100.*s*(1.-s)**4 *t**3 *(1.-t)**2
    H(4,4) = 25.*s*(1.-s)**4 *t**4 *(1.-t) + 100.*s**2 *(1.-s)**3 *t**4 *(1.-t) &
            + 100.*s*(1.-s)**4 *t**3 *(1.-t)**2 + 400.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
    H(4,5) = 10.*s**2 *(1.-s)**3 *t**5 + 50.*s**2 *(1.-s)**3 *t**4 *(1.-t)
    H(4,6) = 10.*(1.-s)**5 *t**3 *(1.-t)**2 + 50.*s*(1.-s)**4 *t**3 *(1.-t)**2
    H(4,7) = 50.*s**2 *(1.-s)**3 *t**4 *(1.-t) + 200.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
    H(4,8) = 50.*s*(1.-s)**4 *t**3 *(1.-t)**2 + 200.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
    H(4,9) = 100.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
    !---------------------------------------------------------- vertex (1) _s
    H_s(1,1) = - 30.*s**2 * (1.-s)**2 * (1.-t)**5 - 150.*s**2 * (1.-s)**2 *t*(1.-t)**4 &
              - 300.*s**2 * (1.-s)**2 * t**2 * (1.-t)**3
    H_s(1,2) = +20.*s*(1.-s)**3 * (1.-t)**5 + 5.*(1.-s)**4 * (1.-t)**5 &
              + 100.*s*(1.-s)**3 *t*(1.-t)**4 + 25.*(1.-s)**4 *t*(1.-t)**4 &
              - 60.*s**2 * (1.-s)**2 * (1.-t)**5 - 300.*s**2 * (1.-s)**2 *t*(1.-t)**4
    H_s(1,3) = - 100.*s*(1.-s)**3 *t*(1.-t)**4 - 400.*s*(1.-s)**3 *t**2 *(1.-t)**3
    H_s(1,4) = +100.*s*(1.-s)**3 *t*(1.-t)**4 + 25.*(1.-s)**4 *t*(1.-t)**4 &
              - 300.*s**2 * (1.-s)**2 *t*(1.-t)**4 + 400.*s*(1.-s)**3 *t**2 *(1.-t)**3 &
              + 100.*(1.-s)**4 *t**2 *(1.-t)**3 - 1200.*s**2 *(1.-s)**2 *t**2 * (1.-t)**3
    H_s(1,5) = -30.*s**2 *(1.-s)**2 *(1.-t)**5 + 20.*s *(1.-s)**3 *(1.-t)**5 &
              - 150.*s**2 *(1.-s)**2 *t*(1.-t)**4 + 100.*s *(1.-s)**3 *t*(1.-t)**4
    H_s(1,6) = - 200.*s*(1.-s)**3 *t**2 *(1.-t)**3
    H_s(1,7) = -150.*s**2 *(1.-s)**2 *t*(1.-t)**4 + 100.*s *(1.-s)**3 *t*(1.-t)**4 &
              - 600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3 + 400.*s *(1.-s)**3 *t**2 *(1.-t)**3
    H_s(1,8) = +200.*s*(1.-s)**3 *t**2 *(1.-t)**3 + 50.*(1.-s)**4 *t**2 *(1.-t)**3 &
              - 600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3
    H_s(1,9) = -300.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3 + 200.*s *(1.-s)**3 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (2) _s
    H_s(2,1) = + 30.*s**2 *(1.-s)**2 *(1.-t)**5 + 150.*s**2 *(1.-s)**2 *t*(1.-t)**4 &
              + 300.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3 
    H_s(2,2) = -5.*s**4 *(1.-t)**5 - 20.*s**3*(1.-s) *(1.-t)**5 &
              - 25.*s**4 *t*(1.-t)**4 - 100.*s**3 *(1.-s)*t*(1.-t)**4 &
              + 60.*s**2 *(1.-s)**2 *(1.-t)**5 + 300.*s**2 *(1.-s)**2 *t*(1.-t)**4
    H_s(2,3) = + 100.*s**3 *(1.-s)*t*(1.-t)**4 + 400.*s**3 *(1.-s) *t**2 *(1.-t)**3
    H_s(2,4) = -25.*s**4 *t*(1.-t)**4 - 100.*s**3 *(1.-s)*t*(1.-t)**4 &
              + 300.*s**2 *(1.-s)**2 *t*(1.-t)**4 - 100.*s**4 *t**2 *(1.-t)**3 &
              - 400.*s**3 *(1.-s) *t**2 *(1.-t)**3 + 1200.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3
    H_s(2,5) = -20.*s**3 *(1.-s) *(1.-t)**5 + 30.*s**2 *(1.-s)**2 *(1.-t)**5 &
              - 100.*s**3 *(1.-s) *t*(1.-t)**4 + 150.*s**2 *(1.-s)**2 *t*(1.-t)**4
    H_s(2,6) = + 200.*s**3 *(1.-s) *t**2 *(1.-t)**3
    H_s(2,7) = -100.*s**3 *(1.-s)*t*(1.-t)**4 + 150.*s**2 *(1.-s)**2 *t*(1.-t)**4 &
              - 400.*s**3 *(1.-s) *t**2 *(1.-t)**3 + 600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3
    H_s(2,8) = -50.*s**4 *t**2 *(1.-t)**3 - 200.*s**3 *(1.-s) *t**2 *(1.-t)**3 &
              + 600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3
    H_s(2,9) = -200.*s**3 *(1.-s) *t**2 *(1.-t)**3 + 300.*s**2 *(1.-s)**2 *t**2 *(1.-t)**3
    !---------------------------------------------------------- vertex (3) _s
    H_s(3,1) = + 30.*s**2 *(1.-s)**2 *t**5 + 150.*s**2 *(1.-s)**2 *t**4 *(1.-t) &
              + 300.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2 
    H_s(3,2) = -5.*s**4 *t**5 - 20.*s**3 *(1.-s) *t**5 - 25.*s**4 *t**4 *(1.-t) &
              - 100.*s**3 *(1.-s) *t**4 *(1.-t) + 60.*s**2 *(1.-s)**2 *t**5 &
              + 300.*s**2 *(1.-s)**2 *t**4 *(1.-t)
    H_s(3,3) = + 100.*s**3 *(1.-s) *t**4 *(1.-t) + 400.*s**3 *(1.-s) *t**3 *(1.-t)**2
    H_s(3,4) = -25.*s**4 *t**4 *(1.-t) - 100.*s**3 *(1.-s) *t**4 *(1.-t) &
              + 300.*s**2 *(1.-s)**2 *t**4 *(1.-t) - 100.*s**4 *t**3 *(1.-t)**2 &
              - 400.*s**3 *(1.-s) *t**3 *(1.-t)**2 + 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2
    H_s(3,5) = -20.*s**3 *(1.-s) *t**5 + 30.*s**2 *(1.-s)**2 *t**5 &
              - 100.*s**3 *(1.-s) *t**4 *(1.-t) + 150.*s**2 *(1.-s)**2 *t**4 *(1.-t)
    H_s(3,6) = 200.*s**3 *(1.-s) *t**3 *(1.-t)**2
    H_s(3,7) = -100.*s**3 *(1.-s) *t**4 *(1.-t) + 150.*s**2 *(1.-s)**2 *t**4 *(1.-t) &
              - 400.*s**3 *(1.-s) *t**3 *(1.-t)**2 + 600.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2 
    H_s(3,8) = -50.*s**4 *t**3 *(1.-t)**2 - 200.*s**3 *(1.-s) *t**3 *(1.-t)**2 &
              + 600.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2
    H_s(3,9) = -200.*s**3 *(1.-s) *t**3 *(1.-t)**2 + 300.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2
    !---------------------------------------------------------- vertex (4) _s
    H_s(4,1) = - 30.*s**2 *(1.-s)**2 *t**5 - 150.*s**2 *(1.-s)**2 *t**4 *(1.-t) &
              - 300.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2
    H_s(4,2) = 20.*s*(1.-s)**3 *t**5 + 5.*(1.-s)**4 *t**5 &
              + 100.*s*(1.-s)**3 *t**4 *(1.-t) + 25.*(1.-s)**4 *t**4 *(1.-t) &
              - 60.*s**2 *(1.-s)**2 *t**5 - 300.*s**2 *(1.-s)**2 *t**4 *(1.-t)
    H_s(4,3) = - 100.*s*(1.-s)**3 *t**4 *(1.-t) - 400.*s*(1.-s)**3 *t**3 *(1.-t)**2
    H_s(4,4) = 100.*s*(1.-s)**3 *t**4 *(1.-t) + 25.*(1.-s)**4 *t**4 *(1.-t) &
              - 300.*s**2 *(1.-s)**2 *t**4 *(1.-t) + 400.*s*(1.-s)**3 *t**3 *(1.-t)**2 &
              + 100.*(1.-s)**4 *t**3 *(1.-t)**2 - 1200.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2
    H_s(4,5) = -30.*s**2 *(1.-s)**2 *t**5 + 20.*s *(1.-s)**3 *t**5 &
              - 150.*s**2 *(1.-s)**2 *t**4 *(1.-t) + 100.*s *(1.-s)**3 *t**4 *(1.-t)
    H_s(4,6) = - 200.*s*(1.-s)**3 *t**3 *(1.-t)**2
    H_s(4,7) = -150.*s**2 *(1.-s)**2 *t**4 *(1.-t) + 100.*s *(1.-s)**3 *t**4 *(1.-t) &
              - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2 + 400.*s *(1.-s)**3 *t**3 *(1.-t)**2
    H_s(4,8) = +200.*s*(1.-s)**3 *t**3 *(1.-t)**2 + 50.*(1.-s)**4 *t**3 *(1.-t)**2 &
              - 600.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2
    H_s(4,9) = -300.*s**2 *(1.-s)**2 *t**3 *(1.-t)**2 + 200.*s *(1.-s)**3 *t**3 *(1.-t)**2
    !---------------------------------------------------------- vertex (1) _t
    H_t(1,1) = - 30.*(1.-s)**5 * t**2 * (1.-t)**2 - 150.*s*(1.-s)**4 *t**2 * (1.-t)**2 &
              - 300.*s**2 * (1.-s)**3 * t**2 * (1.-t)**2
    H_t(1,2) = - 100.*s*(1.-s)**4 *t*(1.-t)**3 - 400.*s**2 * (1.-s)**3 *t*(1.-t)**3
    H_t(1,3) = 20.*(1.-s)**5 *t*(1.-t)**3 + 5.*(1.-s)**5 *(1.-t)**4 &
              + 100.*s*(1.-s)**4 *t*(1.-t)**3 + 25.*s*(1.-s)**4 *(1.-t)**4 &
              - 60.*(1.-s)**5 *t**2 *(1.-t)**2 - 300.*s*(1.-s)**4 *t**2 *(1.-t)**2
    H_t(1,4) = 100.*s*(1.-s)**4 *t*(1.-t)**3 + 25.*s*(1.-s)**4 *(1.-t)**4 &
              + 400.*s**2 * (1.-s)**3 *t*(1.-t)**3 + 100.*s**2 * (1.-s)**3 *(1.-t)**4 &
              - 300.*s*(1.-s)**4 *t**2 *(1.-t)**2 - 1200.*s**2 *(1.-s)**3 *t**2 * (1.-t)**2
    H_t(1,5) = - 200.*s**2 *(1.-s)**3 *t*(1.-t)**3
    H_t(1,6) = -30.*(1.-s)**5 *t**2 *(1.-t)**2 + 20.*(1.-s)**5 *t*(1.-t)**3 &
              - 150.*s*(1.-s)**4 *t**2 *(1.-t)**2 + 100.*s*(1.-s)**4 *t*(1.-t)**3
    H_t(1,7) = 200.*s**2 *(1.-s)**3 *t*(1.-t)**3 + 50.*s**2 *(1.-s)**3 *(1.-t)**4 &
              - 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(1,8) = -150.*s*(1.-s)**4 *t**2 *(1.-t)**2 + 100.*s*(1.-s)**4 *t*(1.-t)**3 &
              - 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2 + 400.*s**2 *(1.-s)**3 *t*(1.-t)**3
    H_t(1,9) = -300.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2 + 200.*s**2 *(1.-s)**3 *t*(1.-t)**3
    !---------------------------------------------------------- vertex (2) _t
    H_t(2,1) = - 30.*s**5 *t**2 *(1.-t)**2 - 150.*s**4 *(1.-s) *t**2 *(1.-t)**2 &
              - 300.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2
    H_t(2,2) = - 100.*s**4 *(1.-s)*t*(1.-t)**3 - 400.*s**3 *(1.-s)**2 *t*(1.-t)**3
    H_t(2,3) = 20.*s**5 *t*(1.-t)**3 + 5.*s**5 *(1.-t)**4 &
              + 100.*s**4 *(1.-s)*t*(1.-t)**3 + 25.*s**4 *(1.-s)*(1.-t)**4 &
              - 60.*s**5 *t**2 *(1.-t)**2 - 300.*s**4 *(1.-s) *t**2 *(1.-t)**2
    H_t(2,4) = 100.*s**4 *(1.-s)*t*(1.-t)**3 + 25.*s**4 *(1.-s)*(1.-t)**4 &
              + 400.*s**3 *(1.-s)**2 *t*(1.-t)**3 + 100.*s**3 *(1.-s)**2 *(1.-t)**4 &
              - 300.*s**4 *(1.-s) *t**2 *(1.-t)**2 - 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2
    H_t(2,5) = - 200.*s**3 *(1.-s)**2 *t*(1.-t)**3
    H_t(2,6) = -30.*s**5 *t**2 *(1.-t)**2 + 20.*s**5 *t*(1.-t)**3 &
              - 150.*s**4 *(1.-s) *t**2 *(1.-t)**2 + 100.*s**4 *(1.-s) *t*(1.-t)**3
    H_t(2,7) = 200.*s**3 *(1.-s)**2 *t*(1.-t)**3 + 50.*s**3 *(1.-s)**2 *(1.-t)**4 &
              - 600.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2
    H_t(2,8) = -150.*s**4 *(1.-s) *t**2 *(1.-t)**2 + 100.*s**4 *(1.-s) *t*(1.-t)**3 &
              - 600.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2 + 400.*s**3 *(1.-s)**2 *t*(1.-t)**3
    H_t(2,9) = -300.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2 + 200.*s**3 *(1.-s)**2 *t*(1.-t)**3
    !---------------------------------------------------------- vertex (3) _t
    H_t(3,1) = + 30.*s**5 *t**2 *(1.-t)**2 + 150.*s**4 *(1.-s) *t**2 *(1.-t)**2 &
              + 300.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2 
    H_t(3,2) = + 100.*s**4 *(1.-s) *t**3 *(1.-t) + 400.*s**3 *(1.-s)**2 *t**3 *(1.-t)
    H_t(3,3) = -5.*s**5 *t**4 - 20.*s**5 *t**3 *(1.-t) &
              - 25.*s**4 *(1.-s) *t**4 - 100.*s**4 *(1.-s) *t**3 *(1.-t) &
              + 60.*s**5 *t**2 *(1.-t)**2 + 300.*s**4 *(1.-s) *t**2 *(1.-t)**2
    H_t(3,4) = -25.*s**4 *(1.-s) *t**4 - 100.*s**4 *(1.-s) *t**3 *(1.-t) &
              - 100.*s**3 *(1.-s)**2 *t**4 - 400.*s**3 *(1.-s)**2 *t**3 *(1.-t) &
              + 300.*s**4 *(1.-s) *t**2 *(1.-t)**2 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2
    H_t(3,5) = + 200.*s**3 *(1.-s)**2 *t**3 *(1.-t)
    H_t(3,6) = -20.*s**5 *t**3 *(1.-t) + 30.*s**5 *t**2 *(1.-t)**2 &
              - 100.*s**4 *(1.-s) *t**3 *(1.-t) + 150.*s**4 *(1.-s) *t**2 *(1.-t)**2
    H_t(3,7) = -50.*s**3 *(1.-s)**2 *t**4 - 200.*s**3 *(1.-s)**2 *t**3 *(1.-t) &
              + 600.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2 
    H_t(3,8) = -100.*s**4 *(1.-s) *t**3 *(1.-t) + 150.*s**4 *(1.-s) *t**2 *(1.-t)**2 &
              - 400.*s**3 *(1.-s)**2 *t**3 *(1.-t) + 600.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2
    H_t(3,9) = -200.*s**3 *(1.-s)**2 *t**3 *(1.-t) + 300.*s**3 *(1.-s)**2 *t**2 *(1.-t)**2
    !---------------------------------------------------------- vertex (4) _t
    H_t(4,1) = + 30.*(1.-s)**5 *t**2 *(1.-t)**2 + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2 &
              + 300.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(4,2) = + 100.*s*(1.-s)**4 *t**3 *(1.-t) + 400.*s**2 *(1.-s)**3 *t**3 *(1.-t)
    H_t(4,3) = -5.*(1.-s)**5 *t**4 - 20.*(1.-s)**5 *t**3 *(1.-t) &
              - 25.*s*(1.-s)**4 *t**4 - 100.*s*(1.-s)**4 *t**3 *(1.-t) &
              + 60.*(1.-s)**5 *t**2 *(1.-t)**2 + 300.*s*(1.-s)**4 *t**2 *(1.-t)**2
    H_t(4,4) = -25.*s*(1.-s)**4 *t**4 - 100.*s*(1.-s)**4 *t**3 *(1.-t) &
              - 100.*s**2 *(1.-s)**3 *t**4 - 400.*s**2 *(1.-s)**3 *t**3 *(1.-t) &
              + 300.*s*(1.-s)**4 *t**2 *(1.-t)**2 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(4,5) = 200.*s**2 *(1.-s)**3 *t**3 *(1.-t)
    H_t(4,6) = -20.*(1.-s)**5 *t**3 *(1.-t) + 30.*(1.-s)**5 *t**2 *(1.-t)**2 &
              - 100.*s*(1.-s)**4 *t**3 *(1.-t) + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2
    H_t(4,7) = -50.*s**2 *(1.-s)**3 *t**4 - 200.*s**2 *(1.-s)**3 *t**3 *(1.-t) &
              + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(4,8) = -100.*s*(1.-s)**4 *t**3 *(1.-t) + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2 &
              - 400.*s**2 *(1.-s)**3 *t**3 *(1.-t) + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
    H_t(4,9) = -200.*s**2 *(1.-s)**3 *t**3 *(1.-t) + 300.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
  endif
end subroutine basisfunctions3
  
  
  
  
  
  
  
  




! We just turn the rest out because we don't want to include 3rd derivatives (yet)
#ifdef DONT_DO_THIS_BELOW
  
  
  
  
  
  
  
  
! Don't expect this will be used directly (use separate derivative routines above instead)
! but it's nice to have all of them in the same place, can be removed lated
! This is a good question in fact: would anyone ever use 3rd order derivatives


!> Subroutine which defines the basis functions derived from
!! a mixed Hermite/Quintic finite element representation.
!!
!! - index 1 : counts the vertex
!! - index 2 : counts the vectors (p,u,v,w,i,j,n,m,k)
!! - the functions are defined on the interval (0,1)(0,1)
pure subroutine basisfunctions_C2bi5(s, t, H, H_s, H_t, H_st, H_ss, H_tt, H_sss, H_ttt, H_sst, H_stt)
  
  implicit none
  
  ! --- Routine parameters
  real*8, intent(in)  :: s                   !< s-coordinate in the element
  real*8, intent(in)  :: t                   !< t-coordinate in the element
  real*8, intent(out) :: H    (4,n_order+1)  !< Basis functions
  real*8, intent(out) :: H_s  (4,n_order+1)  !< Basis functions derived with respect to s
  real*8, intent(out) :: H_t  (4,n_order+1)  !< Basis functions derived with respect to t
  real*8, intent(out) :: H_st (4,n_order+1)  !< Basis functions derived with respect to s and t
  real*8, intent(out) :: H_ss (4,n_order+1)  !< Basis functions derived two times with respect to s
  real*8, intent(out) :: H_tt (4,n_order+1)  !< Basis functions derived two times with respect to t
  real*8, intent(out) :: H_sss(4,n_order+1)  !< Basis functions derived three times with respect to s
  real*8, intent(out) :: H_ttt(4,n_order+1)  !< Basis functions derived three times with respect to t
  real*8, intent(out) :: H_sst(4,n_order+1)  !< Basis functions derived three times with respect to s and t
  real*8, intent(out) :: H_stt(4,n_order+1)  !< Basis functions derived three times with respect to s and t
  
  
  ! --------------------------------------------------------------------------------
  ! -------------- Part-1: The polynomials -----------------------------------------
  ! --------------------------------------------------------------------------------
  
  
  ! --- Polynoms at the first node: vertex (1)
  H(1,1) = (1.-s)**5 * (1.-t)**5 + 5.*s*(1.-s)**4 * (1.-t)**5 &
          + 5.*(1.-s)**5 * t*(1.-t)**4 + 25.*s*(1.-s)**4 * t*(1.-t)**4 &
          + 10.*s**2 * (1.-s)**3 * (1.-t)**5 + 10.*(1.-s)**5 * t**2 * (1.-t)**3 &
          + 50.*s**2 * (1.-s)**3 *t*(1.-t)**4 + 50.*s*(1.-s)**4 *t**2 * (1.-t)**3 &
          + 100.*s**2 * (1.-s)**3 * t**2 * (1.-t)**3
  H(1,2) = 5.*s*(1.-s)**4 * (1.-t)**5 + 25.*s*(1.-s)**4 *t*(1.-t)**4 &
          + 20.*s**2 * (1.-s)**3 * (1.-t)**5 + 100.*s**2 * (1.-s)**3 *t*(1.-t)**4
  H(1,3) = 5.*(1.-s)**5 *t*(1.-t)**4 + 25.*s*(1.-s)**4 *t*(1.-t)**4 &
          + 20.*(1.-s)**5 *t**2 *(1.-t)**3 + 100.*s*(1.-s)**4 *t**2 *(1.-t)**3
  H(1,4) = 25.*s*(1.-s)**4 *t*(1.-t)**4 + 100.*s**2 * (1.-s)**3 *t*(1.-t)**4 &
          + 100.*s*(1.-s)**4 *t**2 *(1.-t)**3 + 400.*s**2 *(1.-s)**3 *t**2 * (1.-t)**3
  H(1,5) = 10.*s**2 *(1.-s)**3 *(1.-t)**5 + 50.*s**2 *(1.-s)**3 *t*(1.-t)**4
  H(1,6) = 10.*(1.-s)**5 *t**2 *(1.-t)**3 + 50.*s*(1.-s)**4 *t**2 *(1.-t)**3
  H(1,7) = 50.*s**2 *(1.-s)**3 *t*(1.-t)**4 + 200.*s**2 *(1.-s)**3 *t**2 *(1.-t)**3
  H(1,8) = 50.*s*(1.-s)**4 *t**2 *(1.-t)**3 + 200.*s**2 *(1.-s)**3 *t**2 *(1.-t)**3
  H(1,9) = 100.*s**2 *(1.-s)**3 *t**2 *(1.-t)**3
  
  ! --- Polynoms at the second node: vertex (2)
  H(2,1) = s**5 *(1.-t)**5 + 5.*s**4*(1.-s) *(1.-t)**5 &
          + 5.*s**5 *t*(1.-t)**4 + 25.*s**4 *(1.-s)*t*(1.-t)**4 &
          + 10.*s**3 *(1.-s)**2 *(1.-t)**5 + 10.*s**5 *t**2 *(1.-t)**3 &
          + 50.*s**3 *(1.-s)**2 *t*(1.-t)**4 + 50.*s**4 *(1.-s) *t**2 *(1.-t)**3 &
          + 100.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3 
  H(2,2) = 5.*s**4*(1.-s) *(1.-t)**5 + 25.*s**4 *(1.-s)*t*(1.-t)**4 &
          + 20.*s**3 *(1.-s)**2 *(1.-t)**5 + 100.*s**3 *(1.-s)**2 *t*(1.-t)**4
  H(2,3) = 5.*s**5 *t*(1.-t)**4 + 25.*s**4 *(1.-s)*t*(1.-t)**4 &
          + 20.*s**5 *t**2 *(1.-t)**3 + 100.*s**4 *(1.-s) *t**2 *(1.-t)**3
  H(2,4) = 25.*s**4 *(1.-s)*t*(1.-t)**4 + 100.*s**3 *(1.-s)**2 *t*(1.-t)**4 &
          + 100.*s**4 *(1.-s) *t**2 *(1.-t)**3 + 400.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
  H(2,5) = 10.*s**3 *(1.-s)**2 *(1.-t)**5 + 50.*s**3 *(1.-s)**2 *t*(1.-t)**4
  H(2,6) = 10.*s**5 *t**2 *(1.-t)**3 + 50.*s**4 *(1.-s) *t**2 *(1.-t)**3
  H(2,7) = 50.*s**3 *(1.-s)**2 *t*(1.-t)**4 + 200.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
  H(2,8) = 50.*s**4 *(1.-s) *t**2 *(1.-t)**3 + 200.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
  H(2,9) = 100.*s**3 *(1.-s)**2 *t**2 *(1.-t)**3
  
  ! --- Polynoms at the fourth node: vertex (3)
  H(3,1) = s**5 *t**5 + 5.*s**4 *(1.-s)*t**5 + 5.*s**5 *t**4 *(1.-t) &
          + 25.*s**4 *(1.-s) *t**4 *(1.-t) + 10.*s**3 *(1.-s)**2 *t**5 &
          + 10.*s**5 *t**3 *(1.-t)**2 + 50.*s**3 *(1.-s)**2 *t**4 *(1.-t) &
          + 50.*s**4 *(1.-s) *t**3 *(1.-t)**2 + 100.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2 
  H(3,2) = 5.*s**4 *(1.-s) *t**5 + 25.*s**4 *(1.-s) *t**4 *(1.-t) &
          + 20.*s**3 *(1.-s)**2 *t**5 + 100.*s**3 *(1.-s)**2 *t**4 *(1.-t)
  H(3,3) = 5.*s**5 *t**4 *(1.-t) + 25.*s**4 *(1.-s) *t**4 *(1.-t) &
          + 20.*s**5 *t**3 *(1.-t)**2 + 100.*s**4 *(1.-s) *t**3 *(1.-t)**2
  H(3,4) = 25.*s**4 *(1.-s) *t**4 *(1.-t) + 100.*s**3 *(1.-s)**2 *t**4 *(1.-t) &
          + 100.*s**4 *(1.-s) *t**3 *(1.-t)**2 + 400.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2
  H(3,5) = 10.*s**3 *(1.-s)**2 *t**5 + 50.*s**3 *(1.-s)**2 *t**4 *(1.-t)
  H(3,6) = 10.*s**5 *t**3 *(1.-t)**2 + 50.*s**4 *(1.-s) *t**3 *(1.-t)**2
  H(3,7) = 50.*s**3 *(1.-s)**2 *t**4 *(1.-t) + 200.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2 
  H(3,8) = 50.*s**4 *(1.-s) *t**3 *(1.-t)**2 + 200.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2
  H(3,9) = 100.*s**3 *(1.-s)**2 *t**3 *(1.-t)**2
  
  ! --- Polynoms at the third node: vertex (4)
  H(4,1) = (1.-s)**5 *t**5 + 5.*s*(1.-s)**4 *t**5 &
          + 5.*(1.-s)**5 *t**4 *(1.-t) + 25.*s*(1.-s)**4 *t**4 *(1.-t) &
          + 10.*s**2 *(1.-s)**3 *t**5 + 10.*(1.-s)**5 *t**3 *(1.-t)**2 &
          + 50.*s**2 *(1.-s)**3 *t**4 *(1.-t) + 50.*s*(1.-s)**4 *t**3 *(1.-t)**2 &
          + 100.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
  H(4,2) = 5.*s*(1.-s)**4 *t**5 + 25.*s*(1.-s)**4 *t**4 *(1.-t) &
          + 20.*s**2 *(1.-s)**3 *t**5 + 100.*s**2 *(1.-s)**3 *t**4 *(1.-t)
  H(4,3) = 5.*(1.-s)**5 *t**4 *(1.-t) + 25.*s*(1.-s)**4 *t**4 *(1.-t) &
          + 20.*(1.-s)**5 *t**3 *(1.-t)**2 + 100.*s*(1.-s)**4 *t**3 *(1.-t)**2
  H(4,4) = 25.*s*(1.-s)**4 *t**4 *(1.-t) + 100.*s**2 *(1.-s)**3 *t**4 *(1.-t) &
          + 100.*s*(1.-s)**4 *t**3 *(1.-t)**2 + 400.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
  H(4,5) = 10.*s**2 *(1.-s)**3 *t**5 + 50.*s**2 *(1.-s)**3 *t**4 *(1.-t)
  H(4,6) = 10.*(1.-s)**5 *t**3 *(1.-t)**2 + 50.*s*(1.-s)**4 *t**3 *(1.-t)**2
  H(4,7) = 50.*s**2 *(1.-s)**3 *t**4 *(1.-t) + 200.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
  H(4,8) = 50.*s*(1.-s)**4 *t**3 *(1.-t)**2 + 200.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
  H(4,9) = 100.*s**2 *(1.-s)**3 *t**3 *(1.-t)**2
  
  
  
  
  ! --------------------------------------------------------------------------------
  ! -------------- Part-2: The s-derivative of the polynomials ---------------------
  ! --------------------------------------------------------------------------------
  
  
  ! --- The s-derivatives at the first node: vertex (1)
  H_s(1,1) = - 30.*s**2 * (1.-s)**2 * (1.-t)**5 - 150.*s**2 * (1.-s)**2 *t*(1.-t)**4 &
            - 300.*s**2 * (1.-s)**2 * t**2 * (1.-t)**3
  H_s(1,2) = +20.*s*(1.-s)**3 * (1.-t)**5 + 5.*(1.-s)**4 * (1.-t)**5 &
            + 100.*s*(1.-s)**3 *t*(1.-t)**4 + 25.*(1.-s)**4 *t*(1.-t)**4 &
            - 60.*s**2 * (1.-s)**2 * (1.-t)**5 - 300.*s**2 * (1.-s)**2 *t*(1.-t)**4
  H_s(1,3) = - 100.*s*(1.-s)**3 *t*(1.-t)**4 - 400.*s*(1.-s)**3 *t**2 *(1.-t)**3
  H_s(1,4) = +100.*s*(1.-s)**3 *t*(1.-t)**4 + 25.*(1.-s)**4 *t*(1.-t)**4 &
            - 300.*s**2 * (1.-s)**2 *t*(1.-t)**4 + 400.*s*(1.-s)**3 *t**2 *(1.-t)**3 &
