              + 600.*(1.-s)**3 *t**2 *(1.-t)**2 - 400.*(1.-s)**3 *t*(1.-t)**3
  H_sst(1,7) = 1200.*s**2 *(1.-s)*t*(1.-t)**3 + 300.*s**2 *(1.-s)*(1.-t)**4 &
              - 2400.*s*(1.-s)**2 *t*(1.-t)**3 - 600.*s*(1.-s)**2 *(1.-t)**4 &
              + 400.*(1.-s)**3 *t*(1.-t)**3 + 100.*(1.-s)**3 *(1.-t)**4 &
              - 3600.*s**2 *(1.-s)*t**2 *(1.-t)**2 + 7200.*s*(1.-s)**2 *t**2 *(1.-t)**2 &
              - 1200.*(1.-s)**3 *t**2 *(1.-t)**2
  H_sst(1,8) = 5400.*s*(1.-s)**2 *t**2 *(1.-t)**2 - 3600.*s*(1.-s)**2 *t*(1.-t)**3 &
              - 3600.*s**2 *(1.-s)*t**2 *(1.-t)**2 + 2400.*s**2 *(1.-s)*t*(1.-t)**3 
  H_sst(1,9) = -1800.*s**2 *(1.-s)*t**2 *(1.-t)**2 + 1200.*s**2 *(1.-s)*t*(1.-t)**3 &
              + 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2 - 2400.*s*(1.-s)**2 *t*(1.-t)**3 &
              - 600.*(1.-s)**3 *t**2 *(1.-t)**2 + 400.*(1.-s)**3 *t*(1.-t)**3
  
  ! --- The sst-derivatives at the second node: vertex (2)
  H_sst(2,1) = + 1800.*s**2 *(1.-s)*t**2 *(1.-t)**2 - 1800.*s*(1.-s)**2 *t**2 *(1.-t)**2
  H_sst(2,2) = + 3600.*s**2 *(1.-s)*t*(1.-t)**3 - 2400.*s*(1.-s)**2 *t*(1.-t)**3
  H_sst(2,3) = -400.*s**3 *t*(1.-t)**3 - 100.*s**3 *(1.-t)**4 &
              + 1200.*s**2 *(1.-s)*t*(1.-t)**3 + 300.*s**2 *(1.-s)*(1.-t)**4 &
              + 1200.*s**3 *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s) *t**2 *(1.-t)**2
  H_sst(2,4) = -3600.*s**2 *(1.-s)*t*(1.-t)**3 - 900.*s**2 *(1.-s)*(1.-t)**4 &
              + 2400.*s*(1.-s)**2 *t*(1.-t)**3 + 600.*s*(1.-s)**2 *(1.-t)**4 &
              + 10800.*s**2 *(1.-s) *t**2 *(1.-t)**2 - 7200.*s*(1.-s)**2 *t**2 *(1.-t)**2
  H_sst(2,5) = - 400.*s**3 *t*(1.-t)**3 + 2400.*s**2*(1.-s) *t*(1.-t)**3 &
              - 1200.*s*(1.-s)**2 *t*(1.-t)**3
  H_sst(2,6) = 600.*s**3 *t**2 *(1.-t)**2 - 400.*s**3 *t*(1.-t)**3 &
              - 1800.*s**2 *(1.-s) *t**2 *(1.-t)**2 + 1200.*s**2 *(1.-s) *t*(1.-t)**3
  H_sst(2,7) = 400.*s**3 *t*(1.-t)**3 + 100.*s**3 *(1.-t)**4 &
              - 2400.*s**2 *(1.-s)*t*(1.-t)**3 - 600.*s**2 *(1.-s)*(1.-t)**4 &
              + 1200.*s*(1.-s)**2 *t*(1.-t)**3 + 300.*s*(1.-s)**2 *(1.-t)**4 &
              - 1200.*s**3 *t**2 *(1.-t)**2 + 7200.*s**2 *(1.-s) *t**2 *(1.-t)**2 &
              - 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2
  H_sst(2,8) = 5400.*s**2 *(1.-s) *t**2 *(1.-t)**2 - 3600.*s**2 *(1.-s) *t*(1.-t)**3 &
              - 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2 + 2400.*s*(1.-s)**2 *t*(1.-t)**3
  H_sst(2,9) = -600.*s**3 *t**2 *(1.-t)**2 + 400.*s**3 *t*(1.-t)**3 &
              + 3600.*s**2 *(1.-s) *t**2 *(1.-t)**2 - 2400.*s**2 *(1.-s) *t*(1.-t)**3 &
              - 1800.*s*(1.-s)**2 *t**2 *(1.-t)**2 + 1200.*s*(1.-s)**2 *t*(1.-t)**3
  
  ! --- The sst-derivatives at the fourth node: vertex (3)
  H_sst(3,1) = - 1800.*s**2 *(1.-s)*t**2 *(1.-t)**2 + 1800.*s*(1.-s)**2 *t**2 *(1.-t)**2 
  H_sst(3,2) =  - 3600.*s**2 *(1.-s) *t**3 *(1.-t) + 2400.*s*(1.-s)**2 *t**3 *(1.-t)
  H_sst(3,3) = 100.*s**3 *t**4 + 400.*s**3 *t**3 *(1.-t) &
              - 300.*s**2 *(1.-s) *t**4 - 1200.*s**2 *(1.-s) *t**3 *(1.-t) &
              - 1200.*s**3 *t**2 *(1.-t)**2 + 3600.*s**2 *(1.-s) *t**2 *(1.-t)**2
  H_sst(3,4) = 900.*s**2 *(1.-s) *t**4 + 3600.*s**2 *(1.-s) *t**3 *(1.-t) &
              - 600.*s*(1.-s)**2 *t**4 - 2400.*s*(1.-s)**2 *t**3 *(1.-t) &
              - 10800.*s**2 *(1.-s)*t**2 *(1.-t)**2 + 7200.*s*(1.-s)**2 *t**2 *(1.-t)**2
  H_sst(3,5) = + 400.*s**3 *t**3 *(1.-t) - 2400.*s**2 *(1.-s) *t**3 *(1.-t) &
              + 1200.*s*(1.-s)**2 *t**3 *(1.-t)
  H_sst(3,6) = 400.*s**3 *t**3 *(1.-t) - 600.*s**3 *t**2 *(1.-t)**2 &
              - 1200.*s**2 *(1.-s) *t**3 *(1.-t) + 1800.*s**2 *(1.-s) *t**2 *(1.-t)**2
  H_sst(3,7) = -100.*s**3 *t**4 - 400.*s**3 *t**3 *(1.-t) &
              + 600.*s**2 *(1.-s) *t**4 + 2400.*s**2 *(1.-s) *t**3 *(1.-t) &
              - 300.*s*(1.-s)**2 *t**4 - 1200.*s*(1.-s)**2 *t**3 *(1.-t) &
              + 1200.*s**3 *t**2 *(1.-t)**2 - 7200.*s**2 *(1.-s) *t**2 *(1.-t)**2 &
              + 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2 
  H_sst(3,8) = 3600.*s**2 *(1.-s) *t**3 *(1.-t) - 5400.*s**2 *(1.-s) *t**2 *(1.-t)**2 &
              - 2400.*s*(1.-s)**2 *t**3 *(1.-t) + 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2
  H_sst(3,9) = -400.*s**3 *t**3 *(1.-t) + 600.*s**3 *t**2 *(1.-t)**2 &
              + 2400.*s**2 *(1.-s) *t**3 *(1.-t) - 3600.*s**2 *(1.-s) *t**2 *(1.-t)**2 &
              - 1200.*s*(1.-s)**2 *t**3 *(1.-t) + 1800.*s*(1.-s)**2 *t**2 *(1.-t)**2
  
  ! --- The sst-derivatives at the third node: vertex (4)
  H_sst(4,1) = + 1800.*s**2 *(1.-s)*t**2 *(1.-t)**2 - 1800.*s*(1.-s)**2 *t**2 *(1.-t)**2
  H_sst(4,2) = - 3600.*s*(1.-s)**2 *t**3 *(1.-t) + 2400.*s**2 *(1.-s)*t**3 *(1.-t)
  H_sst(4,3) = - 300.*s*(1.-s)**2 *t**4 - 1200.*s*(1.-s)**2 *t**3 *(1.-t) &
              + 100.*(1.-s)**3 *t**4 + 400.*(1.-s)**3 *t**3 *(1.-t) &
              + 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2 - 1200.*(1.-s)**3 *t**2 *(1.-t)**2
  H_sst(4,4) = 900.*s*(1.-s)**2 *t**4 + 3600.*s*(1.-s)**2 *t**3 *(1.-t) &
              - 600.*s**2 *(1.-s)*t**4 - 2400.*s**2 *(1.-s)*t**3 *(1.-t) &
              - 10800.*s*(1.-s)**2 *t**2 *(1.-t)**2 + 7200.*s**2 *(1.-s)*t**2 *(1.-t)**2
  H_sst(4,5) = + 1200.*s**2 *(1.-s)*t**3 *(1.-t) - 2400.*s*(1.-s)**2 *t**3 *(1.-t) &
              + 400.*(1.-s)**3 *t**3 *(1.-t)
  H_sst(4,6) = - 1200.*s*(1.-s)**2 *t**3 *(1.-t) + 1800.*s*(1.-s)**2 *t**2 *(1.-t)**2 &
              + 400.*(1.-s)**3 *t**3 *(1.-t) - 600.*(1.-s)**3 *t**2 *(1.-t)**2
  H_sst(4,7) = -300.*s**2 *(1.-s)*t**4 - 1200.*s**2 *(1.-s)*t**3 *(1.-t) &
              + 600.*s*(1.-s)**2 *t**4 + 2400.*s*(1.-s)**2 *t**3 *(1.-t) &
              - 100.*(1.-s)**3 *t**4 - 400.*(1.-s)**3 *t**3 *(1.-t) &
              + 3600.*s**2 *(1.-s)*t**2 *(1.-t)**2 - 7200.*s*(1.-s)**2 *t**2 *(1.-t)**2 &
              + 1200.*(1.-s)**3 *t**2 *(1.-t)**2
  H_sst(4,8) = 3600.*s*(1.-s)**2 *t**3 *(1.-t) - 5400.*s*(1.-s)**2 *t**2 *(1.-t)**2 &
              - 2400.*s**2 *(1.-s)*t**3 *(1.-t) + 3600.*s**2 *(1.-s)*t**2 *(1.-t)**2
  H_sst(4,9) = -1200.*s**2 *(1.-s)*t**3 *(1.-t) + 1800.*s**2 *(1.-s)*t**2 *(1.-t)**2 &
              + 2400.*s*(1.-s)**2 *t**3 *(1.-t) - 3600.*s*(1.-s)**2 *t**2 *(1.-t)**2 &
              - 400.*(1.-s)**3 *t**3 *(1.-t) + 600.*(1.-s)**3 *t**2 *(1.-t)**2
  
      
  
  
  ! --------------------------------------------------------------------------------
  ! -------------- Part-10: The stt-derivative of the polynomials ---------------------
  ! --------------------------------------------------------------------------------
      
  ! --- The stt-derivatives at the first node: vertex (1)
  H_stt(1,1) = - 1800.*s**2 * (1.-s)**2 * t**2 *(1.-t) + 1800.*s**2 * (1.-s)**2 * t*(1.-t)**2
  H_stt(1,2) = 1200.*s*(1.-s)**3 *t*(1.-t)**2 + 300.*(1.-s)**4 *t*(1.-t)**2 &
              - 400.*s*(1.-s)**3 *(1.-t)**3 - 100.*(1.-s)**4 *(1.-t)**3 &
              - 3600.*s**2 * (1.-s)**2 *t*(1.-t)**2 + 1200.*s**2 * (1.-s)**2 *(1.-t)**3
  H_stt(1,3) = 3600.*s*(1.-s)**3 *t*(1.-t)**2 - 2400.*s*(1.-s)**3 *t**2 *(1.-t)
  H_stt(1,4) = -3600.*s*(1.-s)**3 *t*(1.-t)**2 - 900.*(1.-s)**4 *t*(1.-t)**2 &
              + 10800.*s**2 * (1.-s)**2 *t*(1.-t)**2 + 2400.*s*(1.-s)**3 *t**2 *(1.-t) &
              + 600.*(1.-s)**4 *t**2 *(1.-t) - 7200.*s**2 *(1.-s)**2 *t**2 * (1.-t)
  H_stt(1,5) = -1800.*s**2 *(1.-s)**2 *t*(1.-t)**2 + 1200.*s*(1.-s)**3 *t*(1.-t)**2 &
              + 600.*s**2 *(1.-s)**2 *(1.-t)**3 - 400.*s*(1.-s)**3 *(1.-t)**3
  H_stt(1,6) = - 1200.*s*(1.-s)**3 *t**2 *(1.-t) + 2400.*s*(1.-s)**3 *t*(1.-t)**2 &
              - 400.*s*(1.-s)**3 *(1.-t)**3
  H_stt(1,7) = 5400.*s**2 *(1.-s)**2 *t*(1.-t)**2 - 3600.*s*(1.-s)**3 *t*(1.-t)**2 &
              - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t) + 2400.*s*(1.-s)**3 *t**2 *(1.-t)
  H_stt(1,8) = 1200.*s*(1.-s)**3 *t**2 *(1.-t) + 300.*(1.-s)**4 *t**2 *(1.-t) &
