              + 400.*s*(1.-s)**3 *(1.-t)**3 + 100.*(1.-s)**4 *(1.-t)**3 &
              - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t) + 7200.*s**2 *(1.-s)**2 *t*(1.-t)**2 &
              - 1200.*s**2 *(1.-s)**2 *(1.-t)**3
  H_stt(1,9) = -1800.*s**2 *(1.-s)**2 *t**2 *(1.-t) + 1200.*s*(1.-s)**3 *t**2 *(1.-t) &
              + 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2 - 2400.*s*(1.-s)**3 *t*(1.-t)**2 &
              - 600.*s**2 *(1.-s)**2 *(1.-t)**3 + 400.*s*(1.-s)**3 *(1.-t)**3
  
  ! --- The stt-derivatives at the second node: vertex (2)
  H_stt(2,1) = + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t*(1.-t)**2
  H_stt(2,2) = -300.*s**4 *t*(1.-t)**2 - 1200.*s**3 *(1.-s)*t*(1.-t)**2 &
              + 100.*s**4 *(1.-t)**3 + 400.*s**3 *(1.-s)*(1.-t)**3 &
              + 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2 - 1200.*s**2 *(1.-s)**2 *(1.-t)**3
  H_stt(2,3) = - 3600.*s**3 *(1.-s)*t*(1.-t)**2 + 2400.*s**3 *(1.-s) *t**2 *(1.-t)
  H_stt(2,4) = 900.*s**4 *t*(1.-t)**2 + 3600.*s**3 *(1.-s)*t*(1.-t)**2 &
              - 10800.*s**2 *(1.-s)**2 *t*(1.-t)**2 - 600.*s**4 *t**2 *(1.-t) &
              - 2400.*s**3 *(1.-s) *t**2 *(1.-t) + 7200.*s**2 *(1.-s)**2 *t**2 *(1.-t)
  H_stt(2,5) = -1200.*s**3 *(1.-s)*t*(1.-t)**2 + 1800.*s**2 *(1.-s)**2 *t*(1.-t)**2 &
              + 400.*s**3 *(1.-s)*(1.-t)**3 - 600.*s**2 *(1.-s)**2 *(1.-t)**3
  H_stt(2,6) = + 1200.*s**3 *(1.-s) *t**2 *(1.-t) - 2400.*s**3 *(1.-s) *t*(1.-t)**2 &
              + 400.*s**3 *(1.-s) *(1.-t)**3
  H_stt(2,7) = 3600.*s**3 *(1.-s)*t*(1.-t)**2 - 5400.*s**2 *(1.-s)**2 *t*(1.-t)**2 &
              - 2400.*s**3 *(1.-s)*t**2 *(1.-t) + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t) 
  H_stt(2,8) = -300.*s**4 *t**2 *(1.-t) - 1200.*s**3 *(1.-s) *t**2 *(1.-t) &
              + 600.*s**4 *t*(1.-t)**2 + 2400.*s**3 *(1.-s) *t*(1.-t)**2 &
              - 100.*s**4 *(1.-t)**3 - 400.*s**3 *(1.-s) *(1.-t)**3 &
              + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t) - 7200.*s**2 *(1.-s)**2 *t*(1.-t)**2 &
              + 1200.*s**2 *(1.-s)**2 *(1.-t)**3
  H_stt(2,9) = -1200.*s**3 *(1.-s)*t**2 *(1.-t) + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t) &
              + 2400.*s**3 *(1.-s)*t*(1.-t)**2 - 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2 &
              - 400.*s**3 *(1.-s)*(1.-t)**3 + 600.*s**2 *(1.-s)**2 *(1.-t)**3
  
  ! --- The stt-derivatives at the fourth node: vertex (3)
  H_stt(3,1) = - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t) + 1800.*s**2 *(1.-s)**2 *t*(1.-t)**2 
  H_stt(3,2) = 100.*s**4 *t**3 + 400.*s**3 *(1.-s) *t**3 &
              - 300.*s**4 *t**2 *(1.-t) - 1200.*s**3 *(1.-s) *t**2 *(1.-t) &
              - 1200.*s**2 *(1.-s)**2 *t**3 + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)
  H_stt(3,3) = - 3600.*s**3 *(1.-s) *t**2 *(1.-t) + 2400.*s**3 *(1.-s) *t*(1.-t)**2
  H_stt(3,4) = 900.*s**4 *t**2 *(1.-t) + 3600.*s**3 *(1.-s) *t**2 *(1.-t) &
              - 10800.*s**2 *(1.-s)**2 *t**2 *(1.-t) - 600.*s**4 *t*(1.-t)**2 &
              - 2400.*s**3 *(1.-s) *t*(1.-t)**2 + 7200.*s**2 *(1.-s)**2 *t*(1.-t)**2
  H_stt(3,5) = 400.*s**3 *(1.-s)*t**3 - 600.*s**2 *(1.-s)**2 *t**3 &
              - 1200.*s**3 *(1.-s)*t**2 *(1.-t) + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)
  H_stt(3,6) = + 400.*s**3 *(1.-s) *t**3 - 2400.*s**3 *(1.-s) *t**2 *(1.-t) &
              + 1200.*s**3 *(1.-s) *t*(1.-t)**2
  H_stt(3,7) = 3600.*s**3 *(1.-s)*t**2 *(1.-t) - 5400.*s**2 *(1.-s)**2 *t**2 *(1.-t) &
              - 2400.*s**3 *(1.-s)*t*(1.-t)**2 + 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2 
  H_stt(3,8) = -100.*s**4 *t**3 - 400.*s**3 *(1.-s) *t**3 &
              + 600.*s**4 *t**2 *(1.-t) + 2400.*s**3 *(1.-s) *t**2 *(1.-t) &
              - 300.*s**4 *t*(1.-t)**2 - 1200.*s**3 *(1.-s) *t*(1.-t)**2 &
              + 1200.*s**2 *(1.-s)**2 *t**3 - 7200.*s**2 *(1.-s)**2 *t**2 *(1.-t) &
              + 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2
  H_stt(3,9) = -400.*s**3 *(1.-s)*t**3 + 600.*s**2 *(1.-s)**2 *t**3 &
              + 2400.*s**3 *(1.-s)*t**2 *(1.-t) - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t) &
              - 1200.*s**3 *(1.-s)*t*(1.-t)**2 + 1800.*s**2 *(1.-s)**2 *t*(1.-t)**2
  
  ! --- The stt-derivatives at the third node: vertex (4)
  H_stt(4,1) = + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t) - 1800.*s**2 *(1.-s)**2 *t*(1.-t)**2
  H_stt(4,2) = -400.*s*(1.-s)**3 *t**3 - 100.*(1.-s)**4 *t**3 &
              + 1200.*s*(1.-s)**3 *t**2 *(1.-t) + 300.*(1.-s)**4 *t**2 *(1.-t) &
              + 1200.*s**2 *(1.-s)**2 *t**3 - 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)
  H_stt(4,3) = 3600.*s*(1.-s)**3 *t**2 *(1.-t) - 2400.*s*(1.-s)**3 *t*(1.-t)**2
  H_stt(4,4) = -3600.*s*(1.-s)**3 *t**2 *(1.-t) - 900.*(1.-s)**4 *t**2 *(1.-t) &
              + 10800.*s**2 *(1.-s)**2 *t**2 *(1.-t) + 2400.*s*(1.-s)**3 *t*(1.-t)**2 &
              + 600.*(1.-s)**4 *t*(1.-t)**2 - 7200.*s**2 *(1.-s)**2 *t*(1.-t)**2
  H_stt(4,5) = 600.*s**2 *(1.-s)**2 *t**3 - 400.*s*(1.-s)**3 *t**3 &
              - 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t) + 1200.*s*(1.-s)**3 *t**2 *(1.-t)
  H_stt(4,6) = - 400.*s*(1.-s)**3 *t**3 + 2400.*s*(1.-s)**3 *t**2 *(1.-t) &
              - 1200.*s*(1.-s)**3 *t*(1.-t)**2
  H_stt(4,7) = 5400.*s**2 *(1.-s)**2 *t**2 *(1.-t) - 3600.*s*(1.-s)**3 *t**2 *(1.-t) &
              - 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2 + 2400.*s*(1.-s)**3 *t*(1.-t)**2
  H_stt(4,8) = 400.*s*(1.-s)**3 *t**3 + 100.*(1.-s)**4 *t**3 &
              - 2400.*s*(1.-s)**3 *t**2 *(1.-t) - 600.*(1.-s)**4 *t**2 *(1.-t) &
              + 1200.*s*(1.-s)**3 *t*(1.-t)**2 + 300.*(1.-s)**4 *t*(1.-t)**2 &
              - 1200.*s**2 *(1.-s)**2 *t**3 + 7200.*s**2 *(1.-s)**2 *t**2 *(1.-t) &
              - 3600.*s**2 *(1.-s)**2 *t*(1.-t)**2
  H_stt(4,9) = -600.*s**2 *(1.-s)**2 *t**3 + 400.*s*(1.-s)**3 *t**3 &
              + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t) - 2400.*s*(1.-s)**3 *t**2 *(1.-t) &
