            - 100.*s**2 *(1.-s)**3 *t**4 - 400.*s**2 *(1.-s)**3 *t**3 *(1.-t) &
            + 300.*s*(1.-s)**4 *t**2 *(1.-t)**2 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
  H_t(5,4) = 200.*s**2 *(1.-s)**3 *t**3 *(1.-t)
  H_t(6,4) = -20.*(1.-s)**5 *t**3 *(1.-t) + 30.*(1.-s)**5 *t**2 *(1.-t)**2 &
            - 100.*s*(1.-s)**4 *t**3 *(1.-t) + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2
  H_t(7,4) = -50.*s**2 *(1.-s)**3 *t**4 - 200.*s**2 *(1.-s)**3 *t**3 *(1.-t) &
            + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
  H_t(8,4) = -100.*s*(1.-s)**4 *t**3 *(1.-t) + 150.*s*(1.-s)**4 *t**2 *(1.-t)**2 &
            - 400.*s**2 *(1.-s)**3 *t**3 *(1.-t) + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
  H_t(9,4) = -200.*s**2 *(1.-s)**3 *t**3 *(1.-t) + 300.*s**2 *(1.-s)**3 *t**2 *(1.-t)**2
         
  
  
  
  
  ! --------------------------------------------------------------------------------
  ! -------------- Part-4: The ss-derivative of the polynomials ---------------------
  ! --------------------------------------------------------------------------------
  
      
  ! --- The ss-derivatives at the first node: vertex (1)
  H_ss(1,1) = 60.*s**2 *(1.-s)* (1.-t)**5 - 60.*s*(1.-s)**2 * (1.-t)**5 &
             + 300.*s**2 *(1.-s)*t*(1.-t)**4 - 300.*s*(1.-s)**2 *t*(1.-t)**4 &
             + 600.*s**2 *(1.-s)*t**2 * (1.-t)**3 - 600.*s*(1.-s)**2 * t**2 * (1.-t)**3
  H_ss(2,1) = -180.*s*(1.-s)**2 * (1.-t)**5 - 900.*s*(1.-s)**2 *t*(1.-t)**4 &
             + 120.*s**2 *(1.-s)*(1.-t)**5 + 600.*s**2 *(1.-s)*t*(1.-t)**4
  H_ss(3,1) = + 300.*s*(1.-s)**2 *t*(1.-t)**4 - 100.*(1.-s)**3 *t*(1.-t)**4 &
             + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3 - 400.*(1.-s)**3 *t**2 *(1.-t)**3
  H_ss(4,1) = -900.*s*(1.-s)**2 *t*(1.-t)**4 + 600.*s**2 *(1.-s)*t*(1.-t)**4 &
             - 3600.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 2400.*s**2 *(1.-s)*t**2 * (1.-t)**3
  H_ss(5,1) = 60.*s**2 *(1.-s)*(1.-t)**5 - 120.*s*(1.-s)**2 *(1.-t)**5 &
             + 20.*(1.-s)**3 *(1.-t)**5 + 300.*s**2 *(1.-s)*t*(1.-t)**4 &
             - 600.*s*(1.-s)**2 *t*(1.-t)**4 + 100.*(1.-s)**3 *t*(1.-t)**4
  H_ss(6,1) = + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3 - 200.*(1.-s)**3 *t**2 *(1.-t)**3
  H_ss(7,1) = 300.*s**2 *(1.-s)*t*(1.-t)**4 - 600.*s*(1.-s)**2 *t*(1.-t)**4 &
             + 100.*(1.-s)**3 *t*(1.-t)**4 + 1200.*s**2 *(1.-s)*t**2 *(1.-t)**3 &
             - 2400.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 400.*(1.-s)**3 *t**2 *(1.-t)**3
  H_ss(8,1) = -600.*s*(1.-s)**2 *t**2 *(1.-t)**3 + 1200.*s**2 *(1.-s)*t**2 *(1.-t)**3 &
             - 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
  H_ss(9,1) = 600.*s**2 *(1.-s)*t**2 *(1.-t)**3 - 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3 &
             + 200.*(1.-s)**3 *t**2 *(1.-t)**3
          
  ! --- The ss-derivatives at the second node: vertex (2)
  H_ss(1,2) = -60.*s**2 *(1.-s)*(1.-t)**5 + 60.*s*(1.-s)**2 *(1.-t)**5 &
             - 300.*s**2 *(1.-s)*t*(1.-t)**4 + 300.*s*(1.-s)**2 *t*(1.-t)**4 &
             - 600.*s**2 *(1.-s)*t**2 *(1.-t)**3 + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3 
  H_ss(2,2) = - 180.*s**2*(1.-s) *(1.-t)**5 - 900.*s**2 *(1.-s)*t*(1.-t)**4 &
             + 120.*s*(1.-s)**2 *(1.-t)**5 + 600.*s*(1.-s)**2 *t*(1.-t)**4
  H_ss(3,2) = - 100.*s**3 *t*(1.-t)**4 + 300.*s**2 *(1.-s)*t*(1.-t)**4 &
             - 400.*s**3 *t**2 *(1.-t)**3 + 1200.*s**2 *(1.-s) *t**2 *(1.-t)**3
  H_ss(4,2) = - 900.*s**2 *(1.-s)*t*(1.-t)**4 + 600.*s*(1.-s)**2 *t*(1.-t)**4 &
             - 3600.*s**2 *(1.-s) *t**2 *(1.-t)**3 + 2400.*s*(1.-s)**2 *t**2 *(1.-t)**3
  H_ss(5,2) = 20.*s**3 *(1.-t)**5 - 120.*s**2 *(1.-s) *(1.-t)**5 &
             + 60.*s*(1.-s)**2 *(1.-t)**5 + 100.*s**3 *t*(1.-t)**4 &
             - 600.*s**2*(1.-s) *t*(1.-t)**4 + 300.*s*(1.-s)**2 *t*(1.-t)**4
  H_ss(6,2) = - 200.*s**3 *t**2 *(1.-t)**3 + 600.*s**2 *(1.-s) *t**2 *(1.-t)**3
  H_ss(7,2) = 100.*s**3 *t*(1.-t)**4 - 600.*s**2 *(1.-s)*t*(1.-t)**4 &
             + 300.*s*(1.-s)**2 *t*(1.-t)**4 + 400.*s**3 *t**2 *(1.-t)**3 &
             - 2400.*s**2 *(1.-s) *t**2 *(1.-t)**3 + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
  H_ss(8,2) = - 1800.*s**2 *(1.-s) *t**2 *(1.-t)**3 + 1200.*s*(1.-s)**2 *t**2 *(1.-t)**3
  H_ss(9,2) = 200.*s**3 *t**2 *(1.-t)**3 - 1200.*s**2 *(1.-s) *t**2 *(1.-t)**3 &
             + 600.*s*(1.-s)**2 *t**2 *(1.-t)**3
          
  ! --- The ss-derivatives at the fourth node: vertex (3)
  H_ss(1,3) = - 60.*s**2 *(1.-s)*t**5 + 60.*s*(1.-s)**2 *t**5 &
             - 300.*s**2 *(1.-s)*t**4 *(1.-t) + 300.*s*(1.-s)**2 *t**4 *(1.-t) &
             - 600.*s**2 *(1.-s)*t**3 *(1.-t)**2 + 600.*s*(1.-s)**2 *t**3 *(1.-t)**2 
  H_ss(2,3) = - 180.*s**2 *(1.-s) *t**5 - 900.*s**2 *(1.-s) *t**4 *(1.-t) &
             + 120.*s*(1.-s)**2 *t**5 + 600.*s*(1.-s)**2 *t**4 *(1.-t)
  H_ss(3,3) = - 100.*s**3 *t**4 *(1.-t) + 300.*s**2 *(1.-s) *t**4 *(1.-t) &
             - 400.*s**3 *t**3 *(1.-t)**2 + 1200.*s**2 *(1.-s) *t**3 *(1.-t)**2
  H_ss(4,3) = - 900.*s**2 *(1.-s) *t**4 *(1.-t) + 600.*s*(1.-s)**2 *t**4 *(1.-t) &
             - 3600.*s**2 *(1.-s)*t**3 *(1.-t)**2 + 2400.*s*(1.-s)**2 *t**3 *(1.-t)**2
  H_ss(5,3) = 20.*s**3 *t**5 - 120.*s**2 *(1.-s) *t**5 + 60.*s*(1.-s)**2 *t**5 &
             + 100.*s**3 *t**4 *(1.-t) - 600.*s**2 *(1.-s) *t**4 *(1.-t) &
             + 300.*s*(1.-s)**2 *t**4 *(1.-t)
  H_ss(6,3) = -200.*s**3 *t**3 *(1.-t)**2 + 600.*s**2 *(1.-s) *t**3 *(1.-t)**2
  H_ss(7,3) = 100.*s**3 *t**4 *(1.-t) - 600.*s**2 *(1.-s) *t**4 *(1.-t) &
             + 300.*s*(1.-s)**2 *t**4 *(1.-t) + 400.*s**3 *t**3 *(1.-t)**2 &
             - 2400.*s**2 *(1.-s) *t**3 *(1.-t)**2 + 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2 
  H_ss(8,3) = - 1800.*s**2 *(1.-s) *t**3 *(1.-t)**2 + 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2
  H_ss(9,3) = 200.*s**3 *t**3 *(1.-t)**2 - 1200.*s**2 *(1.-s) *t**3 *(1.-t)**2 &
             + 600.*s*(1.-s)**2 *t**3 *(1.-t)**2
          
  ! --- The ss-derivatives at the third node: vertex (4)
  H_ss(1,4) = + 60.*s**2 *(1.-s)*t**5 - 60.*s*(1.-s)**2 *t**5 &
             + 300.*s**2 *(1.-s)*t**4 *(1.-t) - 300.*s*(1.-s)**2 *t**4 *(1.-t) &
             + 600.*s**2 *(1.-s)*t**3 *(1.-t)**2 - 600.*s*(1.-s)**2 *t**3 *(1.-t)**2
  H_ss(2,4) = -60.*s*(1.-s)**2 *t**5 - 900.*s*(1.-s)**2 *t**4 *(1.-t) &
             + 120.*s**2 *(1.-s)*t**5 - 120.*s*(1.-s)**2 *t**5 &
             + 600.*s**2 *(1.-s)*t**4 *(1.-t)
  H_ss(3,4) = + 300.*s*(1.-s)**2 *t**4 *(1.-t) - 100.*(1.-s)**3 *t**4 *(1.-t) &
             + 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2 - 400.*(1.-s)**3 *t**3 *(1.-t)**2
  H_ss(4,4) = -900.*s*(1.-s)**2 *t**4 *(1.-t) + 600.*s**2 *(1.-s)*t**4 *(1.-t) &
             - 3600.*s*(1.-s)**2 *t**3 *(1.-t)**2 + 2400.*s**2 *(1.-s)*t**3 *(1.-t)**2
  H_ss(5,4) = 60.*s**2 *(1.-s)*t**5 - 120.*s*(1.-s)**2 *t**5 &
             + 20.*(1.-s)**3 *t**5 + 300.*s**2 *(1.-s)*t**4 *(1.-t) &
             - 600.*s*(1.-s)**2 *t**4 *(1.-t) + 100.*(1.-s)**3 *t**4 *(1.-t)
  H_ss(6,4) = + 600.*s*(1.-s)**2 *t**3 *(1.-t)**2 - 200.*(1.-s)**3 *t**3 *(1.-t)**2
  H_ss(7,4) = 300.*s**2 *(1.-s)*t**4 *(1.-t) - 600.*s*(1.-s)**2 *t**4 *(1.-t) &
             + 100.*(1.-s)**3 *t**4 *(1.-t) + 1200.*s**2 *(1.-s)*t**3 *(1.-t)**2 &
             - 2400.*s*(1.-s)**2 *t**3 *(1.-t)**2 + 400.*(1.-s)**3 *t**3 *(1.-t)**2
  H_ss(8,4) = -1800.*s*(1.-s)**2 *t**3 *(1.-t)**2 + 1200.*s**2 *(1.-s)*t**3 *(1.-t)**2
  H_ss(9,4) = 600.*s**2 *(1.-s)*t**3 *(1.-t)**2 - 1200.*s*(1.-s)**2 *t**3 *(1.-t)**2 &
             + 200.*(1.-s)**3 *t**3 *(1.-t)**2
          
          
          
  ! --------------------------------------------------------------------------------
  ! -------------- Part-5: The tt-derivative of the polynomials ---------------------
  ! --------------------------------------------------------------------------------
          
          
  ! --- The tt-derivatives at the first node: vertex (1)
  H_tt(1,1) = 60.*(1.-s)**5 * t**2 *(1.-t) - 60.*(1.-s)**5 * t*(1.-t)**2 &
             + 300.*s*(1.-s)**4 *t**2 *(1.-t) - 300.*s*(1.-s)**4 *t*(1.-t)**2 &
             + 600.*s**2 * (1.-s)**3 * t**2 *(1.-t) - 600.*s**2 * (1.-s)**3 * t*(1.-t)**2
