             + 1200.*s**2 * (1.-s)**3 *t*(1.-t)**2 - 400.*s**2 * (1.-s)**3 *(1.-t)**3
  H_tt(3,1) = -180.*(1.-s)**5 *t*(1.-t)**2 - 900.*s*(1.-s)**4 *t*(1.-t)**2 &
             + 120.*(1.-s)**5 *t**2 *(1.-t) + 600.*s*(1.-s)**4 *t**2 *(1.-t)
  H_tt(4,1) = -900.*s*(1.-s)**4 *t*(1.-t)**2 - 3600.*s**2 * (1.-s)**3 *t*(1.-t)**2 &
             + 600.*s*(1.-s)**4 *t**2 *(1.-t) + 2400.*s**2 *(1.-s)**3 *t**2 * (1.-t)
  H_tt(5,1) = 600.*s**2 *(1.-s)**3 *t*(1.-t)**2 - 200.*s**2 *(1.-s)**3 *(1.-t)**3
  H_tt(6,1) = 60.*(1.-s)**5 *t**2 *(1.-t) - 120.*(1.-s)**5 *t*(1.-t)**2 &
             + 20.*(1.-s)**5 *(1.-t)**3 + 300.*s*(1.-s)**4 *t**2 *(1.-t) &
             - 600.*s*(1.-s)**4 *t*(1.-t)**2 + 100.*s*(1.-s)**4 *(1.-t)**3
  H_tt(7,1) = -1800.*s**2 *(1.-s)**3 *t*(1.-t)**2 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t)
  H_tt(8,1) = 300.*s*(1.-s)**4 *t**2 *(1.-t) - 600.*s*(1.-s)**4 *t*(1.-t)**2 &
             + 100.*s*(1.-s)**4 *(1.-t)**3 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t) &
             - 2400.*s**2 *(1.-s)**3 *t*(1.-t)**2 + 400.*s**2 *(1.-s)**3 *(1.-t)**3
  H_tt(9,1) = 600.*s**2 *(1.-s)**3 *t**2 *(1.-t) - 1200.*s**2 *(1.-s)**3 *t*(1.-t)**2 &
             + 200.*s**2 *(1.-s)**3 *(1.-t)**3
          
  ! --- The tt-derivatives at the second node: vertex (2)
  H_tt(1,2) = 60.*s**5 *t**2 *(1.-t) - 60.*s**5 *t*(1.-t)**2 &
             + 300.*s**4 *(1.-s) *t**2 *(1.-t) - 300.*s**4 *(1.-s) *t*(1.-t)**2 &
             + 600.*s**3 *(1.-s)**2 *t**2 *(1.-t) - 600.*s**3 *(1.-s)**2 *t*(1.-t)**2
  H_tt(2,2) = 300.*s**4 *(1.-s)*t*(1.-t)**2 - 100.*s**4 *(1.-s)*(1.-t)**3 &
             + 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2 - 400.*s**3 *(1.-s)**2 *(1.-t)**3
  H_tt(3,2) = -180.*s**5 *t*(1.-t)**2 - 900.*s**4 *(1.-s)*t*(1.-t)**2 &
             + 120.*s**5 *t**2 *(1.-t) + 600.*s**4 *(1.-s) *t**2 *(1.-t)
  H_tt(4,2) = -900.*s**4 *(1.-s)*t*(1.-t)**2 - 3600.*s**3 *(1.-s)**2 *t*(1.-t)**2 &
             + 600.*s**4 *(1.-s) *t**2 *(1.-t) + 2400.*s**3 *(1.-s)**2 *t**2 *(1.-t)
  H_tt(5,2) = 600.*s**3 *(1.-s)**2 *t*(1.-t)**2 - 200.*s**3 *(1.-s)**2 *(1.-t)**3
  H_tt(6,2) = 60.*s**5 *t**2 *(1.-t) - 120.*s**5 *t*(1.-t)**2 &
             + 20.*s**5 *(1.-t)**3 + 300.*s**4 *(1.-s) *t**2 *(1.-t) &
             - 600.*s**4 *(1.-s) *t*(1.-t)**2 + 100.*s**4 *(1.-s) *(1.-t)**3
  H_tt(7,2) = -1800.*s**3 *(1.-s)**2 *t*(1.-t)**2 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t) 
  H_tt(8,2) = 300.*s**4 *(1.-s) *t**2 *(1.-t) - 600.*s**4 *(1.-s) *t*(1.-t)**2 &
             + 100.*s**4 *(1.-s) *(1.-t)**3 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t) &
             - 2400.*s**3 *(1.-s)**2 *t*(1.-t)**2 + 400.*s**3 *(1.-s)**2 *(1.-t)**3
  H_tt(9,2) = 600.*s**3 *(1.-s)**2 *t**2 *(1.-t) - 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2 &
             + 200.*s**3 *(1.-s)**2 *(1.-t)**3
          
  ! --- The tt-derivatives at the fourth node: vertex (3)
  H_tt(1,3) = -60.*s**5 *t**2 *(1.-t) + 60.*s**5 *t*(1.-t)**2 &
             - 300.*s**4 *(1.-s) *t**2 *(1.-t) + 300.*s**4 *(1.-s) *t*(1.-t)**2 &
             - 600.*s**3 *(1.-s)**2 *t**2 *(1.-t) + 600.*s**3 *(1.-s)**2 *t*(1.-t)**2 
  H_tt(2,3) = -100.*s**4 *(1.-s) *t**3 + 300.*s**4 *(1.-s) *t**2 *(1.-t) &
             - 400.*s**3 *(1.-s)**2 *t**3 + 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t)
  H_tt(3,3) = - 180.*s**5 *t**2 *(1.-t) - 900.*s**4 *(1.-s) *t**2 *(1.-t) &
             + 120.*s**5 *t*(1.-t)**2 + 600.*s**4 *(1.-s) *t*(1.-t)**2
  H_tt(4,3) = - 900.*s**4 *(1.-s) *t**2 *(1.-t) - 3600.*s**3 *(1.-s)**2 *t**2 *(1.-t) &
             + 600.*s**4 *(1.-s) *t*(1.-t)**2 + 2400.*s**3 *(1.-s)**2 *t*(1.-t)**2
  H_tt(5,3) = - 200.*s**3 *(1.-s)**2 *t**3 + 600.*s**3 *(1.-s)**2 *t**2 *(1.-t)
  H_tt(6,3) = 20.*s**5 *t**3 - 120.*s**5 *t**2 *(1.-t) &
             + 60.*s**5 *t*(1.-t)**2 + 100.*s**4 *(1.-s) *t**3 &
             - 600.*s**4 *(1.-s) *t**2 *(1.-t) + 300.*s**4 *(1.-s) *t*(1.-t)**2
  H_tt(7,3) = - 1800.*s**3 *(1.-s)**2 *t**2 *(1.-t) + 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2 
  H_tt(8,3) = 100.*s**4 *(1.-s) *t**3 - 600.*s**4 *(1.-s) *t**2 *(1.-t) &
             + 300.*s**4 *(1.-s) *t*(1.-t)**2 + 400.*s**3 *(1.-s)**2 *t**3 &
             - 2400.*s**3 *(1.-s)**2 *t**2 *(1.-t) + 1200.*s**3 *(1.-s)**2 *t*(1.-t)**2
  H_tt(9,3) = 200.*s**3 *(1.-s)**2 *t**3 - 1200.*s**3 *(1.-s)**2 *t**2 *(1.-t) &
             + 600.*s**3 *(1.-s)**2 *t*(1.-t)**2
          
  ! --- The tt-derivatives at the third node: vertex (4)
  H_tt(1,4) = - 60.*(1.-s)**5 *t**2 *(1.-t) + 60.*(1.-s)**5 *t*(1.-t)**2 &
             - 300.*s*(1.-s)**4 *t**2 *(1.-t) + 300.*s*(1.-s)**4 *t*(1.-t)**2 &
             - 600.*s**2 *(1.-s)**3 *t**2 *(1.-t) + 600.*s**2 *(1.-s)**3 *t*(1.-t)**2
  H_tt(2,4) = - 100.*s*(1.-s)**4 *t**3 + 300.*s*(1.-s)**4 *t**2 *(1.-t) &
             - 400.*s**2 *(1.-s)**3 *t**3 + 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t)
  H_tt(3,4) = - 180.*(1.-s)**5 *t**2 *(1.-t) - 900.*s*(1.-s)**4 *t**2 *(1.-t) &
             + 120.*(1.-s)**5 *t*(1.-t)**2 + 600.*s*(1.-s)**4 *t*(1.-t)**2
  H_tt(4,4) = - 900.*s*(1.-s)**4 *t**2 *(1.-t) - 3600.*s**2 *(1.-s)**3 *t**2 *(1.-t) &
             + 600.*s*(1.-s)**4 *t*(1.-t)**2 + 2400.*s**2 *(1.-s)**3 *t*(1.-t)**2
  H_tt(5,4) = -200.*s**2 *(1.-s)**3 *t**3 + 600.*s**2 *(1.-s)**3 *t**2 *(1.-t)
  H_tt(6,4) = 20.*(1.-s)**5 *t**3 - 120.*(1.-s)**5 *t**2 *(1.-t) &
             + 60.*(1.-s)**5 *t*(1.-t)**2 + 100.*s*(1.-s)**4 *t**3 &
             - 600.*s*(1.-s)**4 *t**2 *(1.-t) + 300.*s*(1.-s)**4 *t*(1.-t)**2
  H_tt(7,4) = - 1800.*s**2 *(1.-s)**3 *t**2 *(1.-t) + 1200.*s**2 *(1.-s)**3 *t*(1.-t)**2
  H_tt(8,4) = 100.*s*(1.-s)**4 *t**3 - 600.*s*(1.-s)**4 *t**2 *(1.-t) &
             + 300.*s*(1.-s)**4 *t*(1.-t)**2 + 400.*s**2 *(1.-s)**3 *t**3 &
             - 2400.*s**2 *(1.-s)**3 *t**2 *(1.-t) + 1200.*s**2 *(1.-s)**3 *t*(1.-t)**2
  H_tt(9,4) = 200.*s**2 *(1.-s)**3 *t**3 - 1200.*s**2 *(1.-s)**3 *t**2 *(1.-t) &
             + 600.*s**2 *(1.-s)**3 *t*(1.-t)**2
          
          
          
