             - 1200.*s*(1.-s)**3 *t**2 *(1.-t)**2 - 300.*(1.-s)**4 *t**2 *(1.-t)**2 &
             + 3600.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2
  H_st(5,1) = + 600.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 400.*s *(1.-s)**3 *t*(1.-t)**3
  H_st(6,1) = 600.*s*(1.-s)**3 *t**2 *(1.-t)**2 - 400.*s*(1.-s)**3 *t*(1.-t)**3
  H_st(7,1) = -600.*s**2 *(1.-s)**2 *t*(1.-t)**3 - 150.*s**2 *(1.-s)**2 *(1.-t)**4 &
             + 400.*s *(1.-s)**3 *t*(1.-t)**3 + 100.*s *(1.-s)**3 *(1.-t)**4 &
             + 1800.*s**2 *(1.-s)**2 *t**2 *(1.-t)**2 - 1200.*s *(1.-s)**3 *t**2 *(1.-t)**2
  H_st(8,1) = -600.*s*(1.-s)**3 *t**2 *(1.-t)**2 + 400.*s*(1.-s)**3 *t*(1.-t)**3 &
